// كتاب الطهارة — القسم الثاني: من باب استحباب إطالة الغرة والتحجيل (ص77–...)
const { NO_N, NO_O } = require('../b4/common');

module.exports = [
  {
    title: `باب استحباب إطالة الغرة والتحجيل في الوضوء (ص77–88)`,
    items: [
      { q: `إطالة الغرة والتحجيل: معناها وقدر المستحب منها، وهل غسل المنكبين والركبتين بدعة؟`, p: `78–81`,
        n: `اعلم أن هذه الأحاديث مصرحة باستحباب تطويل الغرة والتحجيل. أما تطويل الغرة فقال أصحابنا: هو غسل شيء من مقدم الرأس وما يجاوز الوجه زائد على الجزء الذي يجب غسله لاستيقان كمال الوجه. وأما تطويل التحجيل فهو غسل ما فوق المرفقين والكعبين، وهذا مستحب بلا خلاف بين أصحابنا، واختلفوا في قدر المستحب على أوجه: أحدها: أنه يستحب الزيادة فوق المرفقين والكعبين من غير توقيت. والثاني: يستحب إلى نصف العضد والساق. والثالث: يستحب إلى المنكبين والركبتين، وأحاديث الباب تقتضي هذا كله. وأما دعوى الإمام أبي الحسن بن بطال المالكي والقاضي عياض اتفاق العلماء على أنه لا يستحب الزيادة فوق المرفق والكعب فباطلة، وكيف تصح دعواهما وقد ثبت فعل ذلك عن رسول الله ﷺ وأبي هريرة ﵁؟ وهو مذهبنا لا خلاف فيه عندنا كما ذكرناه، ولو خالف فيه مخالف كان محجوجًا بهذه السنن الصحيحة الصريحة. وأما احتجاجهما بقوله ﷺ: «من زاد على هذا أو نقص فقد أساء وظلم» فلا يصح؛ لأن المراد من زاد في عدد المرات.`,
        o: `ابن بطال والقاضي عياض: اتفق العلماء على أنه لا يستحب الزيادة فوق المرفق والكعب.`,
        s: `(تطويل الغرة): فالإنسان لا يحصل له يقين تام من غسل الوجه، أو لا يمكن غسل كامل الوجه إلا بغسل بدايات الشعر، فهذا الجزء ما لا يتم الواجب إلا به فهو واجب، وأما أن يغسل جزءًا زائدًا عليه من الرأس فهذا الذي فيه الكلام. والوجه الأول (الزيادة من غير توقيت) هو أصح الأقوال؛ لأن حديث أبي هريرة المرفوع (حتى أشرع في العضد ... حتى أشرع في الساق) ولم يحدد النصف أو أكثر، فالصحيح أنه يشرع أي يبدأ. والثاني (إلى نصف العضد والساق) يحتاج إلى دليل. والثالث (إلى المنكبين والركبتين) هذا وضوء أبي هريرة ﵁، ولكن الظاهر أنه من رأيه واجتهاده الذي لم يوافقه أحد غيره من الصحابة ﵃، وهذا وإن كان اجتهاد صحابي بدليل أنه قال في الحديث التالي: [فقال: يا بني فروخ أنتم ها هنا؟ لو علمت أنكم ها هنا ما توضأت هذا الوضوء] إذًا فقد كان أمر يراه من قبل نفسه، وهذا دليل على أنهم كانوا يرونه يتوضأ وضوء السنة؛ لأنه ما اجتهد فيه الصحابي مخالفًا فيه الصحابة وقد تركه عامة الصحابة فليس من السنة، فالمشروع هو ما فعله النبي ﷺ، ولو كان يشرع الزيادة لفعلها النبي ﷺ؛ ولهذا كثير من العلماء يقولون ببدعية غسل المنكبين والركبتين رغم استحباب ذلك عند الشافعية ورغم ثبوت ذلك من فعل أبي هريرة ﵁، وذلك لأن هذا مما خالفه فيه غيره من الصحابة الذين هم أعلم منه ﵁ ممن نقلوا وضوء النبي ﷺ، وقد أكد أن هذا اجتهاد منه. ولكن قد يقال: إن هذا مما يسوغ فيه الاجتهاد (بعض الصحابة فهم فهمًا خالف فيه غيره من أئمة الصحابة كانت المسألة مما يسوغ فيها الخلاف)، ولكن هذا لا يمنع من أن نقول أن هذا القول ليس بصحيح أو أنه بدعة وأنه ليس بمشروع، كما يمثل لذلك شيخ الإسلام: غسل ابن عمر ﵁ باطن عينيه حتى عمي، ولا يُشرع غسل باطن العينين، وإنما غسل ﷺ ظاهر العينين فقط والجفون من الخارج، ولم يُنقل عنه ﷺ قط أنه غسل باطن العينين ولا أنه تعمد فتح العينين في الماء. ففعل بعض الصحابة ذلك لا يدل على السنية مطلقًا مع وجود من يخالفهم ومع التصريح أنه أمر اجتهادي منهم؛ فهذه المسألة لا بد من ردها إلى الأدلة، وقد مثل لذلك ابن تيمية: إن صح الأثر عن عثمان بن حنيف في تعليم الرجل الذي له حاجة عند عثمان بن عفان دعاء التوسل الوارد في حديث الأعمى [قال له عثمان بن حنيف: ائت الميضأة فتوضأ، ثم ائت المسجد فصلِّ فيه ركعتين وقل: «اللهم إني أسألك وأتوجه إليك بنبينا نبي الرحمة، يا محمد إني أتوجه بك إلى ربك فيقضي لي حاجتي»، وتذكر حاجتك] الدعاء للطبراني. وكان ذلك بعد وفاة النبي ﷺ ولم يدعو له النبي ﷺ حتى كنت متوسلًا بدعائه، فدل على أن عثمان بن حنيف فهم من (أتوسل إليك بنبيك) أنه توسل إليه بذاته وإلا لما أمره بذلك بعد وفاته ﷺ، وإلا لو كان متصورًا أنه بدعائه فعلًا (أتوسل إليك بنبيك) أي بدعاء نبيك، لما أمره أن يدعو بهذا الدعاء وهو لم يدعو له، ولكن ظاهر هذا الكلام أنه فهم منه أن هذا توسل بذات النبي ﷺ فأجازه بعد وفاة النبي ﷺ لوجود ذاته، وهذا رغم ضعفه إسنادًا لعثمان بن حنيف ﵁ إلا أنه لو صح لكان دليلًا على هذا مما يسوغ فيه الاجتهاد وقد خالفه غيره من الصحابة فيه فلا يكون حجة. وشيخ الإسلام مثل أيضًا: بأكل بعض الصحابة البرد وهو صائم مستجيز ذلك، وبعض السلف كان يأكل حتى يسفر جدًّا وليس عند طلوع الفجر فقط في الصيام، وهذه من الأخطاء التي لا شك فيها والأقوال المعلوم بطلانها بالأدلة الصحيحة من الكتاب والسنة؛ ففعل الصحابة ﵃ إذا خالف نصوص الكتاب والسنة فلا بد من رده، وإذا كان من أقوال الصحابة من قال أو فعل غير قول بعضهم والدليل مع قول هذا الآخر كانت هذه المسألة مما يسوغ فيه الاجتهاد، ولكن لا يقال هذا قول الصحابي فيكون حجة في هذا كما فعل الشافعي في هذه المسألة. فالشافعية رأوا أن فعل أبي هريرة حجة فقالوا باستحباب الغسل حتى المنكبين والساقين، فهذا مرجوح قول ضعيف؛ فهذا من فعل أبي هريرة الذي أشار إلى أنه ليس من سنة النبي ﷺ فقال: (ما توضأت هذا الوضوء) فإنه ما كان يشعر أن أحدًا يقتدي به وعندما كان يعلم بوجود من يقتضي به كان بعدما يذكر الوضوء (ثم غسل رجله اليمنى حتى أشرع في الساق ثم غسل رجله اليسرى حتى أشرع في الساق ثم قال: هكذا رأيت رسول الله ﷺ يتوضأ)، ولذلك نقول المستحب هو الشروع في العضد والساق. وأما قول ابن بطال والقاضي: نعم هذا في مطلق الزيادة لا في الوصول إلى المنكبين؛ لأن الجزء المرفوع إلى النبي ﷺ هو (حتى أشرع في العضد)، وأما جزء الإطالة إلى المنكبين فضلًا عن نصف الساق (أو نصف العضد) فهذا ليس بصحيح مرفوعًا، فالتحديد ليس عليه دليل، و(الوصول إلى المنكبين) فهو موقوف على أبي هريرة. وعمومًا فإن مذهب المالكية في باب سد الذرائع والبدع من أقوى المذاهب في هذا الباب. وأما حديث «من زاد على هذا» فهذا ليس بمطلق؛ فلو أنه تعبد بغسل أعضاء لم ترد وواظب على ذلك تعبدًا أو ولو مرة واحدة تعبدًا بدون دليل لكان ذلك بدعة وظلم وإساءة، فلو أنه في كل مرة يمسح رقبته في الوضوء لكان هذا من البدع لأنه لم يرد عنه ﷺ، وكذلك الزيادة في عدد المرات من البدع ومن الإساءة والظلم، فكلامه هنا ليس على إطلاقه. أما من نقص فالمقصود ليس في عدد المرات بل في الأعضاء لثبوت أن النبي ﷺ نقص عن الثلاث. فإذا لم يثبت عن النبي ﷺ أنه غسل المنكبين والركبتين دل ذلك على عدم مشروعية غسلهما وأنه على الراجح تعدي وإساءة، ولكن المسألة فيها اجتهاد، فعلى الراجح تعني وجود الاجتهاد فيها، وعدم ترجيح مشروعية الغسل إلى المنكبين ليس معناه أنه يلزم تبديع كل شخص أو أنه يُحكم عليه بالإساءة بشخصه أو أنه آثم بذلك بشخصه فقد يمنع من ذلك مانع؛ فالتفسيق والتبديع والتضليل والحكم بثبوت الإثم عليه مثل مسائل التكفير، فهناك فرق بين النوع والعين، فقد يجتهد مجتهد وعمل بما أداه إليه اجتهاده وهو من أهل الاجتهاد لا يأثم بذلك وكان له أجر حتى وإن أخطأ وللمصيب أجران. وهذا دليل أن بعض مسائل البدع مختلف فيها، فالبعض يظن بأن القول بأن هذا الأمر بدعة أنه لا يحتمل اجتهادًا، فلا يلزم منه تبديع وتضليل كل من فعله، فتبديع المعين مبني على استيفاء الشروط وانتفاء الموانع مثل مسائل التكفير، كما يقول ابن تيمية: [فإن نصوص «الوعيد» التي في الكتاب والسنة ونصوص الأئمة بالتكفير والتفسيق ونحو ذلك لا يستلزم ثبوت موجبها في حق المعين إلا إذا وجدت الشروط وانتفت الموانع، لا فرق في ذلك بين الأصول والفروع] مجموع الفتاوى؛ فبالإجماع لا يذم أبو هريرة لأنه غسل المنكبين لأنه على قول الشافعية سنة وعلى قول الآخرين اجتهاد قد أخطأ فيه فله أجر.`,
        f: [
          `(ص78) على قوله في مسلم «فليذادن رجال عن حوضي»: بدلًا من [ألا ليذادن رجال عن حوضي]، وهذا من دقة الإمام مسلم رحمه الله.`,
          `(ص81) على قوله «أشرع في العضد وأشرع في الساق» معناه أدخل الغسل فيهما: هذا هو الجزء المرفوع إلى النبي ﷺ فإنه قال: (حتى أشرع في الساق ثم قال: هكذا رأيت رسول الله ﷺ يتوضأ).`,
          `(ص82) «السيما» العلامة: فيقول (سيما) أو (سيماء).`,
          `(ص82) على قوله ﷺ «وإني لأصد الناس عنه» و«أذود»: يمنع الأمم الأخرى من أن ترد على حوضه توفيرًا للشراب الذي في الحوض لأمته، وهذا من كمال شفقته ﷺ، مع كون هذا الحوض واسع جدًّا («إن حوضي لأبعد من أيلة [وهي على ساحل البحر الأبيض المتوسط قرب القدس] من [أي: إلى] عدن [التي هي في جنوب الجزيرة العربية]») فحوض النبي ﷺ طوله في عرضه أكثر من طول الجزيرة العربية وزيادة، ومع كون هذا الشراب من شراب الجنة لا ينفد وهو لكل من شربه، ولكن من كمال شفقته ولأنه لم يؤذن شرعًا لأحد من غير هذه الأمة أن يشرب من حوضه ﷺ.`,
          `(ص87) «الدلاء»: الجرادل، و«الرشا»: الحبال.`,
        ] },
      { q: `هل الوضوء من خصائص هذه الأمة؟`, p: `82`,
        n: `وقد استدل جماعة من أهل العلم بهذا الحديث على أن الوضوء من خصائص هذه الأمة — زادها الله تعالى شرفًا —. وقال آخرون: ليس الوضوء مختصًّا بها وإنما الذي اختصت به هذه الأمة الغرة والتحجيل، واحتجوا بالحديث الآخر: «هذا وضوئي ووضوء الأنبياء قبلي». وأجاب الأولون عن هذا بجوابين: أحدهما: أنه حديث ضعيف معروف الضعف. والثاني: لو صح احتمل أن يكون الأنبياء اختصت بالوضوء دون أممهم إلا هذه الأمة.`,
        o: `قيل: الوضوء ليس مختصًّا بهذه الأمة، وإنما اختصت بالغرة والتحجيل.`,
        s: `نعم لا شك في ضعف الحديث («هذا وضوئي ووضوء الأنبياء قبلي»). وأما احتمال اختصاص الأنبياء بالوضوء دون أممهم: أي أمرت الأمة بالوضوء مثل نبيها، والصحيح أنه حديث ضعيف فلا يعتمد به.` },
      { q: `المراد بمن يُذادون عن الحوض «قد بدلوا بعدك» (المرتدون أم المنافقون أم أهل البدع والكبائر)`, p: `82–84`,
        n: `قوله «وهل تدري ما أحدثوا بعدك» وفي الرواية الأخرى «قد بدلوا بعدك فأقول سحقًا سحقًا»: هذا مما اختلف العلماء في المراد به على أقوال: أحدها: أن المراد به المنافقون والمرتدون، فيجوز أن يحشروا بالغرة والتحجيل فيناديهم النبي ﷺ للسيما التي عليهم فيقال: ليس هؤلاء مما وعدت بهم، إن هؤلاء بدلوا بعدك، أي لم يموتوا على ما ظهر من إسلامهم. والثاني: أن المراد من كان في زمن النبي ﷺ ثم ارتد بعده فيناديهم النبي ﷺ وإن لم يكن عليهم سيما الوضوء لما كان يعرفه ﷺ في حياته من إسلامهم فيقال: ارتدوا بعدك. والثالث: أن المراد به أصحاب المعاصي والكبائر الذين ماتوا على التوحيد وأصحاب البدع الذين لم يخرجوا ببدعتهم عن الإسلام، وعلى هذا القول لا يقطع لهؤلاء الذين يذادون بالنار، بل يجوز أن يذادوا عقوبة لهم ثم يرحمهم الله سبحانه وتعالى فيدخلهم الجنة بغير عذاب. قال أصحاب هذا القول: ولا يمتنع أن يكون لهم غرة وتحجيل، ويحتمل أن يكونوا كانوا في زمن النبي ﷺ وبعده لكن عرفهم بالسيما. وقال الإمام الحافظ أبو عمر بن عبد البر: كل من أحدث في الدين فهو من المطرودين عن الحوض كالخوارج والروافض وسائر أصحاب الأهواء، قال: وكذلك الظلمة المسرفون في الجور وطمس الحق والمعلنون بالكبائر، قال: وكل هؤلاء يخاف عليهم أن يكونوا ممن عنوا بهذا الخبر.`,
        o: `الأقوال الثلاثة المذكورة، وقول ابن عبد البر.`,
        s: `الظاهر والله أعلم أنهم هم المرتدون الذين كانوا من أصحابه ﷺ وليسوا المنافقين؛ لأن هؤلاء المشار إليهم في الحديث بدلوا فهذا دليل على أنهم كانوا على حال وبدلوها، فالظاهر أنه من ارتد من الأعراب وبعض القبائل الذين ارتدوا بعد النبي ﷺ، وهذا من قوله ﷺ: («فأقول: يا رب هؤلاء من أصحابي») فعلم النبي ﷺ أنهم من أصحابه ممن لقيه مؤمنًا؛ ولذلك من تعريف أهل العلم للصحابي: أنه من لقي النبي ﷺ مؤمنًا أو مسلمًا ثم مات على ذلك، ويقول ابن حجر: ولو تخلل ذلك ردة على الصحيح، لكن عمومًا لا بد وأن يموت على الإسلام؛ ولذلك من بدل بعد النبي ﷺ ردة فهو مردود عن الحوض بالكلية. وفي الروايات التصريح بذلك ففي صحيح البخاري: [«ثم يؤخذ برجال من أصحابي ذات اليمين وذات الشمال، فأقول: أصحابي، فيقال: إنهم لم يزالوا مرتدين على أعقابهم منذ فارقتهم، فأقول كما قال العبد الصالح عيسى ابن مريم: ﴿وَكُنْتُ عَلَيْهِمْ شَهِيدًا مَا دُمْتُ فِيهِمْ فَلَمَّا تَوَفَّيْتَنِي كُنْتَ أَنْتَ الرَّقِيبَ عَلَيْهِمْ وَأَنْتَ عَلَى كُلِّ شَيْءٍ شَهِيدٌ﴾ إلى قوله: ﴿الْعَزِيزُ الْحَكِيمُ﴾» قال محمد بن يوسف ذُكر عن أبي عبد الله عن قبيصة قال: هم المرتدون الذين ارتدوا على عهد أبي بكر فقاتلهم أبو بكر ﵁]. وهذا القول (الثالث) لا يصح مع رواية (أصحابي)؛ لأنه لم يعرف عن أحد من الصحابة قط أنه كان من أهل البدع محدثًا بعد النبي ﷺ، ولذلك اتفق العلماء على أن الصحابة كلهم عدول، ولكن هذا القول ينطبق على بعض الروايات الأخرى كقوله ﷺ في بعض الروايات (أمتي أمتي) فهي أوسع من كلمة (أصحابي) فتشمل كل مبتدع، وهناك رواية في البخاري تؤكد على أنه لا يلزم أن يخلدوا في النار أو يقطع لهم بها وهو قوله ﷺ: («بينا أنا قائم إذا زمرة، حتى إذا عرفتهم خرج رجل من بيني وبينهم فقال: هلم، فقلت: أين؟ قال: إلى النار والله، قلت: ما شأنهم؟ قال: إنهم ارتدوا بعدك على أدبارهم القهقرى، فلا أراه يخلص منهم إلا مثل همل النعم») (البخاري 20/250)، وهو دليل على نجاة قلة من أهل البدع، وهذا يدل على خطورة البدع؛ فإن عامة أهل البدع إما أنهم حرموا التوحيد أو ماتوا على غير التوحيد أو أنهم لا ينجوا منهم من أول وهلة إلا مثل همل النعم (الغنم المريضة المهملة القليلة التي تسير وراء الركب) من أجل أنهم أخطأوا وغفر لهم خطأهم لما كانوا عليه من اجتهاد. ولذا فالقول الثالث صحيح ولكن لا ينطبق على الروايات التي فيها (أصحابي)، والقول الأول والثاني صحيح وهو منطبق على الروايات التي فيها (أصحابي). ويمكن أن يكون بعض الناس منافقين مثل من قال عنه ﷺ: («لا، إن له أصحابًا يحقر أحدكم صلاته مع صلاتهم وصيامه مع صيامهم، يمرقون من الدين كمروق السهم من الرمية») ففي بعض رؤوس البدع من المنافقين الذين بدلوا بعد النبي ﷺ وأظهروا التبديل.` },
      { q: `الاستثناء في قوله ﷺ «وإنا إن شاء الله بكم لاحقون» مع أن الموت لا شك فيه`, p: `84–85`,
        n: `وأما قوله ﷺ «وإنا إن شاء الله بكم لاحقون» فأتى بالاستثناء مع أن الموت لا شك فيه، وللعلماء فيه أقوال: أظهرها: أنه ليس للشك ولكنه ﷺ قاله للتبرك وامتثال أمر الله تعالى في قوله: ﴿وَلَا تَقُولَنَّ لِشَيْءٍ إِنِّي فَاعِلٌ ذَلِكَ غَدًا * إِلَّا أَنْ يَشَاءَ اللَّهُ﴾. والثاني: حكاه الخطابي وغيره أنه عادة للمتكلم يحسن به كلامه. والثالث: أن الاستثناء عائد إلى اللحوق في هذا المكان. وقيل: معناه إذ شاء الله. وقيل: أقوال أخر ضعيفة جدًّا تركتها لضعفها وعدم الحاجة إليها، منها قول من قال: الاستثناء منقطع راجع إلى استصحاب الإيمان، وقول من قال: كان معه ﷺ مؤمنون حقيقة وآخرون يظن بهم النفاق فعاد الاستثناء إليهم، وهذان القولان — وإن كانا مشهورين — فيهما خطأ ظاهر.`,
        o: `الأقوال المذكورة في المتن.`,
        s: `(منقطع: أي إنا بكم لاحقون إن شاء الله مؤمنين.) وأحسنها القول الأول أنه للتبرك والله أعلم.` },
      { q: `تمني رؤية الإخوان، ومعنى «أنتم أصحابي وإخواننا الذين لم يأتوا بعد»، وهل يكون فيمن بعد الصحابة من هو أفضل من بعضهم؟`, p: `85–87`,
        n: `قال العلماء: في هذا الحديث جواز التمني لا سيما في الخير ولقاء الفضلاء وأهل الصلاح، والمراد بقوله ﷺ «وددت أنا قد رأينا إخواننا» أي رأيناهم في الحياة الدنيا. قال القاضي عياض: وقيل: المراد تمني لقائهم بعد الموت. قال الإمام الباجي: قوله ﷺ «بل أنتم أصحابي» ليس نفيًا لإخوتهم ولكن ذكر مرتبتهم الزائدة بالصحبة. قال القاضي عياض: ذهب أبو عمر بن عبد البر في هذا الحديث وغيره من الأحاديث في فضل من يأتي آخر الزمان إلى أنه قد يكون فيمن يأتي بعد الصحابة من هو أفضل ممن كان من جملة الصحابة، وأن قوله ﷺ «خيركم قرني» على الخصوص معناه: خير الناس قرني أي السابقون الأولون من المهاجرين والأنصار ومن سلك مسلكهم، فهؤلاء أفضل الأمة وهم المرادون بالحديث، وأما من خلط في زمنه ﷺ وإن رآه وصحبه أو لم يكن له سابقة ولا أثر في الدين فقد يكون في القرون التي تأتي بعد القرن الأول من يفضلهم على ما دلت عليه الآثار. قال القاضي: وقد ذهب إلى هذا أيضًا غيره من المتكلمين على المعاني. قال: وذهب معظم العلماء إلى خلاف هذا، وأن من صحب النبي ﷺ ورآه مرة من عمره وحصلت له مزية الصحبة أفضل من كل من يأتي بعده، فإن فضيلة الصحبة لا يعدلها عمل، قالوا: وذلك فضل الله يؤتيه من يشاء، واحتجوا بقوله ﷺ: «لو أنفق أحدكم مثل أحد ذهبًا ما بلغ مد أحدهم ولا نصيفه».`,
        o: `القاضي عياض (قيل): المراد تمني لقائهم بعد الموت. ومعظم العلماء: من رأى النبي ﷺ مرة أفضل من كل من يأتي بعده.`,
        s: `بل ليس كذلك (أن المراد لقاؤهم بعد الموت)، الظاهر تمني رؤيتهم في الدنيا؛ لأنه سيلقاهم بعد الموت في الآخرة. وأما قول ابن عبد البر فهذا هو الصحيح الذي لا نشك في صحته، وقد قال تعالى: ﴿قَالَتِ الْأَعْرَابُ آمَنَّا قُلْ لَمْ تُؤْمِنُوا وَلَكِنْ قُولُوا أَسْلَمْنَا﴾، وعلى الراجح أنهم ليسوا منافقين بل ناقصي الإيمان، وليس كل من نافق في عهده كان منافقًا النفاق الأكبر؛ قال ﷺ: («آية المنافق ثلاث: إذا حدث كذب، وإذا وعد أخلف، وإذا اؤتمن خان») وهذا نفاق عمل لا يخرج من الملة، فقد وجد في زمنه ﷺ من هو كذلك، ولا شك أن هناك ممن أتى بعد عصر الصحابة من ليس فيهم تلك الخصال وليس فيه نفاق وقد حقق الإيمان الواجب، ونسبة القول بأنه لا يوجد أحد بعد الصحابة من حقق الإيمان الواجب نسبة هذا القول للجمهور باطل بلا شك، بل الحديث يدل على وجود السابقين في كل قرن ولقوله ﷺ: (في كل قرن من أمتي سابق) إذًا هناك سابقون من المتأخرين في هذه الأمة والسابقون أفضل من أصحاب اليمين، وقد قال ﷻ: ﴿عُرُبًا أَتْرَابًا * لِأَصْحَابِ الْيَمِينِ * ثُلَّةٌ مِنَ الْأَوَّلِينَ * وَثُلَّةٌ مِنَ الْآخِرِينَ﴾ وقال عن السابقين: ﴿وَالسَّابِقُونَ السَّابِقُونَ * أُولَئِكَ الْمُقَرَّبُونَ * فِي جَنَّاتِ النَّعِيمِ * ثُلَّةٌ مِنَ الْأَوَّلِينَ * وَقَلِيلٌ مِنَ الْآخِرِينَ﴾ والراجح أنها من هذه الأمة، فإذًا يوجد سابقين من المتأخرين ويوجد أصحاب يمين من المتقدمين، فقد يكون من يأتي بعد الصحابة أفضل من بعض من هم في عوام من صحب النبي ﷺ ممن خلط وممن وقع في نفاق أصغر وممن ارتكب كبائر، وكذلك ولا يلزم من ذلك أن يكون مجموع الصحابة غير مفضل بل جملة الصحابة مفضلون وليس كل واحد فرد، وأما السابقون الأولون فلا يسبقهم أحد فقد أخبر بذلك ﷻ فقال: ﴿وَآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْ﴾، وأيضًا يدل على ذلك أن النبي ﷺ قال عن الشاب الذي يقتله الدجال: (هذا خير الشهداء عند الله)، والأحاديث والأدلة في وجود الخير في أمة الإسلام في آخرها بل في كل قرن ما يلزم منه صحة هذا القول؛ بالإضافة إلى أنه يوجد من المتقدمين من هو ظالم ومن هو من الأبرار وجماعة كثيرة من السابقين، فلو قلنا كل فرد من أفراد الصحابة متقدم على كل من أتى بعده لزم أن يكون كل من أتى بعده من الظالمين لأنفسهم، ولا يلزم ذلك بل يوجد منهم أبرار ويوجد منهم سابقين، ولكن العدد الأكبر من السابقين في الصحابة ثم التابعين ثم تابعي التابعين، والأبرار جماعة كثيرة من الأولين ومن المتأخرين ويوجد قلة من الصحابة الذين ظلموا أنفسهم. وقول معظم العلماء «فضيلة الصحبة لا يعدلها عمل»: ما الدليل على أن (فضيلة الصحبة لا يعدلها عمل) وأن من نظر إلى النبي ﷺ نظرة أو نظر إليه النبي ﷺ نظرة؟ فمحمد بن أبي بكر فقد رآه النبي ﷺ ورأى النبي ﷺ وهو طفل لا يدرك ولا يعي، فأين الدليل على أن (فضيلة الصحبة لا يعدلها عمل)؟ ربما تدل الأدلة على فضيلة الصحبة وفقط ولكن أين (لا يعدلها عمل)؟! وحديث «لو أنفق أحدكم مثل أحد ذهبًا» قاله النبي ﷺ لمن صحبه لخالد بن الوليد ﵁ لما نازع عبد الرحمن بن عوف، والمراد أصحابه المخصوصون من السابقين الأولين، وليس كل من صحبه لأنه كان يخاطب من صحبه، وهذا من العام الذي أريد به الخاص.`, },
    ],
  },
  {
    title: `باب تبلغ الحلية حيث يبلغ الوضوء (ص88–89)`,
    items: [
      { q: `كلام أبي هريرة «لو علمت أنكم ها هنا ما توضأت هذا الوضوء» وعدم الترخص أو التشدد بحضرة العامة`, p: `88–89`,
        n: `قال القاضي عياض: أراد أبو هريرة هنا الموالي وكان خطابه لأبي حازم. قال القاضي: وإنما أراد أبو هريرة بكلامه هذا أنه لا ينبغي لمن يقتدى به إذا ترخص في أمر لضرورة أو تشدد فيه لوسوسة أو لاعتقاده في ذلك مذهبًا شذ به عن الناس أن يفعله بحضرة العامة الجهلة لئلا يترخصوا برخصته لغير ضرورة أو يعتقدوا أن ما تشدد فيه هو الفرض اللازم. هذا كلام القاضي.`,
        o: NO_O,
        s: `تقدم في الباب السابق أن غسل أبي هريرة إلى المنكبين والساقين من اجتهاده، وقد أشار بقوله هذا إلى أنه ليس من سنة النبي ﷺ، فما كان يشعر أن أحدًا يقتدي به، وعندما كان يعلم بوجود من يقتدي به كان يذكر الوضوء المرفوع (حتى أشرع في العضد ... حتى أشرع في الساق)؛ ولذلك نقول المستحب هو الشروع في العضد والساق.` },
    ],
  },
  {
    title: `باب فضل إسباغ الوضوء على المكاره (ص89–91)`,
    items: [
      { q: `معنى «محو الخطايا» و«انتظار الصلاة بعد الصلاة» و«فذلكم الرباط»`, p: `89–91`,
        n: `قال القاضي عياض: محو الخطايا كناية عن غفرانها، قال: ويحتمل محوها من كتاب الحفظة ويكون دليلًا على غفرانها. ورفع الدرجات إعلاء المنازل في الجنة، وإسباغ الوضوء تمامه، والمكاره تكون بشدة البرد وألم الجسم ونحو ذلك، وكثرة الخطا تكون ببعد الدار وكثرة التكرار. وانتظار الصلاة بعد الصلاة: قال القاضي أبو الوليد الباجي: هذا في المشتركتين من الصلوات في الوقت، وأما غيرهما فلم يكن من عمل الناس. وقوله «فذلكم الرباط» أي الرباط المرغب فيه، وأصل الرباط الحبس على الشيء كأنه حبس نفسه على هذه الطاعة، قيل: ويحتمل أنه أفضل الرباط كما قيل: الجهاد جهاد النفس، ويحتمل أنه الرباط المتيسر الممكن أي أنه من أنواع الرباط. هذا آخر كلام القاضي وكله حسن إلا قول الباجي في انتظار الصلاة فإن فيه نظرًا. وأما حكمة تكراره فقيل: للاهتمام به وتعظيم شأنه، وقيل: كرره ﷺ على عادته في تكرار الكلام ليفهم عنه، والأول أظهر.`,
        o: `الباجي: انتظار الصلاة بعد الصلاة في المشتركتين في الوقت (الظهر والعصر، والمغرب والعشاء) فقط.`,
        s: `(محوها من كتاب الحفظة) وهذا أقرب: أن تمحى من الكتاب الذي يحصى فيه أعمال العباد، فإذا كان يوم القيامة لم تُخرج له هذه الخطايا. وقول الباجي: أي ينتظر ما بين الظهر والعصر وما بين المغرب والعشاء، أما ما بين العصر والمغرب فلم يكن من عمل الصحابة، وهذا فيه نظر لقوله ﷺ: «لأن أقعد مع قوم يذكرون الله تعالى من صلاة الغداة حتى تطلع الشمس أحب إلي من أن أعتق أربعة من ولد إسماعيل، ولأن أقعد مع قوم يذكرون الله من صلاة العصر إلى أن تغرب الشمس أحب إلي من أن أعتق أربعة»، وهو دليل على انتظار المغرب من بعد العصر، وكذلك قول السلف في ساعة الجمعة (لا يوافقها عبد مسلم يصلي) فقالوا في تفسيرها: أن منتظر الصلاة فهو في صلاة ولا يلزم أن يكون في صلاة قائمًا، وإنما يكون مجتهدًا في الذكر منتظرًا للصلاة، وهذا يدل على ما ذكرناه من أنه قول ضعيف، فانتظار الصلاة لا يلزم أن يكون المجموعتين مشتركتين في الوقت. والظاهر أن المرابطة نوع من الجهاد، وهي المذكورة في قوله تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا﴾ ولم يكن في عهد النبي ﷺ ثغور يرابطون عليها على الدوام خشية هجوم العدو على البلد، فكان الرباط المأمور به الصحابة هو المواظبة على إصلاح النفس بهذه الطريقة، ولا شك أن الآية تشمل الأنواع الأخرى التي ظهرت بعد العصور الأولى والأحاديث الواردة في فضل الرباط على الثغور كثيرة جدًّا. وهذا دليل على ارتباط [الظاهر بالباطن] و[جهاد النفس بجهاد الكفار] و[المرابطة على الطاعة بالمرابطة في مواجهة الأعداء]، وهذا الوصف من النبي ﷺ (فذلكم الرباط) يؤكد على هذا التلازم خلافًا للجهلة الذين يظنون أن أمر الجهاد لا دخل له بإصلاح النفس، وليس كذلك أنه يهمل جهاد الأعداء بدعوى إصلاح النفس فإنها لا تصلح إلا بعمل الطاعة، فإذا أوجب الله ﷻ الجهاد والرباط على الأمة أو على أفراد منها أو استطاعوا ذلك فتركوه لم يكونوا مصلحين لأنفسهم ولو بقوا في المساجد ليل نهار. وأما حكمة التكرار: فالأول (للاهتمام به وتعظيم شأنه) أظهر بالفعل.` },
    ],
  },
  {
    title: `باب السواك (ص91–100)`,
    items: [
      { q: `معنى السواك، وهل فرشة الأسنان سواك؟ وحكم الاستياك بالأصبع`, p: `92–94`,
        n: `قال أهل اللغة: السواك بكسر السين وهو يطلق على الفعل وعلى العود الذي يتسوك به ... وهو في اصطلاح العلماء استعمال عود أو نحوه في الأسنان لتذهب الصفرة وغيرها عنها. ويستحب أن يستاك بعود من أراك، وبأي شيء استاك مما يزيل التغير حصل السواك كالخرقة الخشنة والسعد والأشنان. وأما الأصبع فإن كانت لينة لم يحصل بها السواك، وإن كانت خشنة ففيها ثلاثة أوجه لأصحابنا: المشهور: لا تجزي، والثاني: تجزي، والثالث: تجزي إن لم يجد غيرها ولا تجزي إن وجد.`,
        o: `الأوجه الثلاثة عند الشافعية في الأصبع الخشنة.`,
        s: `(أو نحوه) أي عود؛ ولذلك نقول أن فرشة الأسنان هي سواك وليست بديلة عن السواك كما يقول البعض، فإن عود الأراك هو أشهر ما اتخذه العرب في ذلك، فأي عود يذهب الصفرة فهو كذلك. والأصبع فيه خلاف ولكن العود نفسه ليس فيه خلاف. وفي الأصبع: فالمشهور (لا تجزي) هو الأقرب؛ لأن الأمر يحتاج إلى دليل للجواز والاستحباب.` },
      { q: `حكم السواك: هل هو واجب؟ وقول داود وإسحاق`, p: `93`,
        n: `ثم إن السواك سنة ليس بواجب في حال من الأحوال لا في الصلاة ولا في غيرها بإجماع من يعتد به في الإجماع. وقد حكى الشيخ أبو حامد الإسفراييني إمام أصحابنا العراقيين عن داود الظاهري أنه أوجبه للصلاة، وحكاه الماوردي عن داود وقال: هو عنده واجب لو تركه لم تبطل صلاته، وحُكي عن إسحاق بن راهويه أنه قال: هو واجب فإن تركه عمدًا بطلت صلاته. وقد أنكر أصحابنا المتأخرون على الشيخ أبي حامد وغيره نقل الوجوب عن داود وقالوا: مذهبه أنه سنة كالجماعة، ولو صح إيجابه عن داود لم تضر مخالفته في انعقاد الإجماع على المختار الذي عليه المحققون والأكثرون، وأما إسحاق فلم يصح هذا المحكي عنه.`,
        o: `حُكي عن داود: واجب للصلاة. وعن إسحاق: واجب تبطل الصلاة بتركه عمدًا.`,
        s: `([كالجماعة] أي كبقية العلماء.) فيرون أن مخالفة الظاهرية ليست ممن يحتج بهم في مخالفة الإجماع، كأنه لا يحتج به أصلًا كأحد أهل العلم الكبار، والصحيح في المسألة أن الإجماع لا يضره مخالفة الواحد والاثنين؛ لأن النبي ﷺ قال: (لا تزال طائفة من أمتي على الحق ظاهرين) فلا بد وأن يكون على الحق في كل زمن طائفة، فإذا كان واحد فلا يسمى الواحد طائفة، حتى لو سمي طائفة لسمي ظاهرًا، فإن قول النبي ﷺ: (لا تزال طائفة من أمتي على الحق ظاهرين لا يضرهم) فكل هذا يدل على الجمع وأدنى الجمع ثلاثة، فالصحيح في مسألة مخالفة الواحد والاثنين أنها لا تقدح في الإجماع سواء كان داود أو غيره. وكيف يوجبونه وقد قال النبي ﷺ: «لولا أن أشق على أمتي لأمرتهم بالسواك عند كل صلاة»؟!` },
      { q: `الأوقات التي يتأكد فيها السواك، ومنها عند الوضوء (هل يستاك مرة ثانية عند الصلاة؟)`, p: `93–94`,
        n: `ثم إن السواك مستحب في جميع الأوقات ولكن في خمسة أوقات أشد استحبابًا: أحدها: عند الصلاة سواء كان متطهرًا بماء أو بتراب أو غير متطهر كمن لم يجد ماء ولا ترابًا. الثاني: عند الوضوء. الثالث: عند قراءة القرآن. الرابع: عند الاستيقاظ من النوم. الخامس: عند تغير الفم، وتغيره يكون بأشياء منها: ترك الأكل والشرب، ومنها أكل ما له رائحة كريهة، ومنها طول السكوت، ومنها كثرة الكلام.`,
        o: NO_O,
        s: `(«كمن لم يجد ماء ولا ترابًا»: أي فاقد الطهورين، يصلي على تلك الحال على أصح أقوال العلماء لأنه عجز عن غير ذلك.) وهو يجعلها — أي عند الوضوء — غير عند الصلاة، والذي يظهر من حديث ابن عباس ﵁ أنه إذا كان مع التقارب («فتسوك وتوضأ ثم قام فصلى») فيستحب عند الوضوء أو قبل الوضوء ولا يكرره عند الصلاة طالما كان الزمن قريبًا، أما إذا صلى بعد مدة فيستحب لإزالة رائحة الفم؛ فهناك أحاديث صحيحة تذكر [عند كل صلاة] وأخرى صحيحة تذكر [عند كل وضوء]، فحديث ابن عباس يدل على أنه («فتسوك وتوضأ ثم قام فصلى») فلم يذكر ابن عباس ﵁ أن النبي ﷺ استاك مرة ثانية؛ وذلك أنه إذا استاك مباشرة قبل الوضوء وصلى عقبه فقد استاك عند الصلاة. وعند الاستيقاظ من النوم لحديث: («كان إذا قام من الليل يشوص فاه بالسواك»).` },
      { q: `السواك للصائم بعد الزوال`, p: `94`,
        n: `ومذهب الشافعي أن السواك يكره للصائم بعد زوال الشمس لئلا يزيل رائحة الخلوف المستحبة.`,
        o: `الشافعي: يكره للصائم بعد الزوال.`,
        s: `الظاهر والله أعلم أنه لا يكره لقول النبي ﷺ: («لولا أن أشق على أمتي لأمرتهم بالسواك عند كل صلاة»)، وهذه صلوات؛ صلوات الظهر والعصر صلوات في نهار الصيام وهي داخله في هذا العموم، والخلوف لا يقصد ابتداء فهو يقع من غير قصد، فإذا كان كذلك فإنه لا يقصد استمراره أيضًا فلا يشرع قصد استمراره وهو محبوب عند الله إذا وقع من غير قصد، ومثل ذلك قال رسول الله ﷺ: («ما من مكلوم يكلم في الله إلا جاء يوم القيامة وكلمه يدمى، اللون لون دم والريح ريح مسك»)، هذا الدم عند الله دم طيب، ولكن هل يشرع أن يترك مع أنه وقع بغير قصد الإنسان؟ فهل جرح ولا يشرع أن يقصد جرح نفسه، فكذلك لا يشرع له أن يترك الدم على نفسه لأنه يأتي يوم القيامة على هذه الصفة، فكذلك، والله أعلى وأعلم.` },
      { q: `صفة الاستياك (عرضًا أو طولًا) وما يستحب فيه`, p: `94–95`,
        n: `والمستحب أن يستاك بعود متوسط لا شديد اليبس يجرح ولا رطب لا يزيل. والمستحب أن يستاك عرضًا ولا يستاك طولًا لئلا يدمي لحم أسنانه، فإن خالف واستاك طولًا حصل السواك مع الكراهة. ويستحب أن يمر السواك أيضًا على طرف أسنانه وكراسي أضراسه وسقف حلقه إمرارًا لطيفًا. ويستحب أن يبدأ في سواكه بالجانب الأيمن من فيه، ولا بأس باستعمال سواك غيره بإذنه، ويستحب أن يعود الصبي السواك ليعتاده.`,
        o: NO_O,
        s: `(الاستياك عرضًا) الحديث في ذلك ضعيف لا يثبت فلا كراهة، وجرح اللثة لا يحصل إلا إذا كان بها مرض. (وإمراره على اللسان) للحديث: (دخلت على النبي ﷺ وطرف السواك على لسانه).` },
      { q: `دلالة حديث «لولا أن أشق على أمتي لأمرتهم» على أن الأمر للوجوب، وهل المندوب مأمور به؟ (الأمر والحقيقة والمجاز)`, p: `95–97`,
        n: `قوله ﷺ: «لولا أن أشق على المؤمنين أو على أمتي لأمرتهم بالسواك عند كل صلاة»: فيه دليل على أن السواك ليس بواجب، قال الشافعي رحمه الله تعالى: لو كان واجبًا لأمرهم به شق أو لم يشق. قال جماعات من العلماء من الطوائف: فيه دليل على أن الأمر للوجوب، وهو مذهب أكثر الفقهاء وجماعات من المتكلمين وأصحاب الأصول. قالوا: وجه الدلالة أنه مسنون بالاتفاق، فدل على أن المتروك إيجابه، وهذا الاستدلال يحتاج في تمامه إلى دليل على أن السواك كان مسنونًا حالة قوله ﷺ: «لولا أن أشق على أمتي لأمرتهم». وقال جماعة أيضًا: فيه دليل على أن المندوب ليس مأمورًا به، وهذا فيه خلاف لأصحاب الأصول، ويقال في هذا الاستدلال ما قدمناه في الاستدلال على الوجوب.`,
        o: `جماعة: المندوب ليس مأمورًا به (وفيه خلاف لأصحاب الأصول).`,
        s: `وهو من أقوى الأدلة على ذلك (أن الأمر للوجوب)، وهذا دليل على أن الأصول يكون الاحتجاج فيها يكون بالسنة، فقوله («لأمرتهم») فلو كان (الأمر) لغير الوجوب لما كان فيه مشقة. الأمر للوجوب ما لم يصرفه صارف، هذا عند جماهير الفقهاء وبعض أصحاب الأصول، و(الأمر) كما يدل عليه الحديث («لأمرتهم») فيه إلزام وخاف ﷺ أن يكون هذا فيه مشقة، ولو كان الأمر يمكن أن يكون للاستحباب أو الإباحة أو غير ذلك في الظاهر لما كان في الأمر مشقة، والصحيح أن الأمر له استعمالات متعددة ولكن ظاهره الوجوب فهو الأصل الذي يجب أن يحمل عليه ما لم يقترن بقرينة تدل على عدم الوجوب، سواء كانت القرينة متصلة (في نفس سياق الكلام) أو منفصلة عنه (كما لو أمر الشرع بأمر وأقر من تركه أو هو ﷺ نفسه تركه مرة أو مرات ليبين أن الأمر ليس للوجوب). ومما يدل على أن الأمر للوجوب قوله ﷻ: ﴿قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ﴾ فجعل اللوم والذم عليه لأنه ترك الأمر، فلفظ الأمر يقتضي الوجوب. وأما قوله «يحتاج إلى دليل على أنه كان مسنونًا حالة قوله»: يقصدون أنه قد شرع بعد ذلك، والصحيح أنه لا يحتاج إلى ذلك لأن هذا بمجرده «لولا أن أشق على أمتي لأمرتهم» فهذا يستدل به عامة العلماء — وهو يفيد ذلك — أنه مستحب عند كل صلاة من غير أدلة أخرى من فعل النبي ﷺ في ذلك الوقت أو بعده. فإن النبي ﷺ قال: «لأمرتهم» فهل هذا الحديث يدل على أن السواك ليس بمشروع؟ لا، فهو مشروع ومستحب، إذًا فما الذي تركه ﷺ خوف المشقة؟ هل ترك أمر الاستحباب أم أمر الإيجاب؟ بل ترك أمر الإيجاب؛ لذلك الخلاف في أن [المندوب ليس مأمورًا به] هذا الكلام فيه نظر والخلاف فيه قريب من اللفظي؛ فقد يقال هذا أمر إيجاب وهذا أمر استحباب، فلو قال إنه غير مأمور به بالكلية فهذا الذي فيه نظر لأنه طلب بدرجة من درجات الطلب ولكن ليس أمرًا حتميًّا، وإلا فكثير من المندوبات ورد الشرع بالأمر بها ولكن مع القرائن الدالة على أنها ليست حتمية واجبة، وبهذا فإن المندوب مأمور به ولكن ليس أمر إيجاب، فالخلاف فيه خلاف لفظي لأنهم سيسمونه مأمورًا به وسيقولون [نحمل الأمر على ظاهره] فعندهم طالما ليس واجبًا فليس مأمورًا به، ولكن الصحيح كما قلنا أن الأمر ظاهره الوجوب وقد يدل على غير ذلك ويستعمل لغير ذلك بالقرينة، وهذا موجود بكثرة في الكتاب والسنة مثل: (اعملوا ما شئتم)، (وقل الحق من ربكم فمن شاء فليؤمن ومن شاء فليكفر) فهذا أمر للتهديد، وقوله ﷺ: (صلوا قبل المغرب صلوا قبل المغرب ثم قال في الثالثة: لمن شاء) فهذا للاستحباب، وهناك للتخيير والتسوية (اصبروا أو لا تصبروا سواء عليكم)، وهناك للإباحة (وإذا حللتم فاصطادوا) فكلها أوامر ولكن مع وجود القرينة، فلا يمنع أن يكون المأمور به غير واجب بقرينة. والأمر بالاستحباب أمر على سبيل المجاز هو معنى أن نقول خلاف الظاهر، فكلمة الظاهر تساوي الحقيقة، وهذا خلاف لفظي أيضًا؛ لأن هذا هو استعمال الأمر في معنى من معانيه المجازية وهو المستحب، فالأمر يستعمل في الاستحباب مجازًا لأن هذا خلاف الظاهر — خلاف حقيقة الأمر — فهو خلاف لأغلب استعمال الأمر. والخلاف في مسألة الحقيقة والمجاز خلاف الصحيح أنه لفظي، فهل في اللغة تقسيم إلى حقيقة ومجاز أم لا؟ الخلاف الذي ذكره شيخ الإسلام ابن تيمية وقال أنه لا يوجد شيء أسمه حقيقة ومجاز أصلًا، مع أن هذا تقسيم اصطلاحي، والمقصود أن الكلمة لها أكثر من استعمال في اللغة، استعمال أغلب واستعمال أقل، ولا شك أن العرب كانوا يستخدمون كلمات يغلب عليها استعمال هذه الكلمة فيه والناس عمومًا وفي كل زمن فيغلب عليهم استعمال كلمة في معنى معين وتكون لها في أصل اللغة وعند غيرهم استعمال آخر وعدة استعمالات. وابن تيمية لم ينكره بالكلية ولكنه أنكر التقسيم، وفي الحقيقة فإن إنكار التقسيم يكون له معنى إذا كان سيبنى عليه حكم شرعي، وإلا فإنكار تقسيم اصطلاحي لا معنى له لأنه سوف لا ينبني عليها أحكام، فالأحكام تبنى على الأدلة، لا تبنى على تقسيم يخترعه الناس، فأي تقسيم اصطلاحي يمكن للناس أن تغيره، يقولون سنسمي هذا الشيء بكذا ونسمي الآخر كذا، واتفقوا على ذلك وارتضوا نقول لا!!! مثل تقسيم العلوم إلى فقه ومصطلح وعقيدة وغير ذلك فهذا تقسيم اصطلاحي وليس تقسيم شرعي، فلم يقسم الشرع هذا، والتقسيم الشرعي هو الذي يكون بدليل، ولذلك لا ينبغي إنكار التقسيم الاصطلاحي إلى حقيقة ومجاز، وإنما أراد بذلك رد كلام المتأولين للصفات، وهذا كلام صحيح فلا بد وأن يُرد ولكن يرد ليس لأن التقسيم غير جائز ولكن يُرد لأن القرينة غير صحيحة وأن الدليل غير صحيح، فصرف اللفظ عن ظاهره لدليل يقترن به أو لقرينة تقترن به، لا بد وأن تكون هذه القرينة صحيحة حتى يكون هذا استعمال صحيح للكلمة ويكون المعنى معنى مقصود. فلا شك عند أحد ولا عند شيخ الإسلام ابن تيمية أنه لو ثبتت القرينة ولو ثبت الدليل الصحيح، يكون استعمال الكلمة في المعنى الأقل استعمالًا استعمال صحيح، وهذا في الحقيقة من باب التفسير وهو القول بالمجاز أو القول بخلاف الظاهر، فهذه الكلمات كلها مضمونها واحد في النهاية، وذلك أن يقول: [الحقيقة — الظاهر — الأصل] في الأمر الوجوب؛ كل ذلك بمعنى واحد، ونقول أيضًا (حقيقة الأمر الوجوب ويستعمل مجازًا في غيره بدليل)، (ويستعمل في خلاف الظاهر بدليل)، (ويستعمل خلاف الأصل بدليل) فهذه الألفاظ كلها بمعنى واحد. ودليل آخر في مسألة أن الأمر للوجوب في الأصل أو في الظاهر أو في حقيقته أن النبي ﷺ قال لمن سأله: (أفي كل عام يا رسول الله؟ فقال: لو قلتها لوجبت، ولو وجبت لم تعملوا بها، ولم تستطيعوا أن تعملوا بها) فقوله: (لو قلتها لوجبت) لأنه قال: (أفي كل عام) وهذا دليل على أن الأمر للوجوب والأمر من النبي ﷺ للوجوب، وليس أن الأمر من الله ﷻ في القرآن فقط هو للوجوب وذلك لأن الأمر من النبي ﷺ أمر من عند الله ﷻ، وهذا الحديث دليل على لزوم السنة كالقرآن — حديث الباب وحديث الحج — فلو كانت السنة التي هي كلام النبي ﷺ وأوامره عمومًا لا يُستفاد منه الوجوب أبدًا، لما كان هناك معنى للمشقة لأنه طالما لم يتنزل في القرآن فليس بواجب على قول القرآنيين المبتدعين وليسوا بقرآنيين لو كانوا قرآنيين لقالوا بمقتضى ما في القرآن من قوله تعالى: (وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا)، فهؤلاء مبتدعين ضلال فيقولون نأخذ بالقرآن ولا نأخذ بالسنة، فهذا الحديث يدل على لزوم السنة لأن النبي ﷺ قال: (لأمرتهم) فلو أمرهم لكان لازمًا عليهم ولكان فيه مشقة لأن الصحابة لم يكن في وسعهم تركه، فهذا دليل على أن كلام النبي ﷺ في التشريع ككلام الله ﷻ في التشريع يعني بذلك في إلزام الحكم وليس في أنه ككلام الله في الصفة لأن كلام الله صفته غير مخلوق، ولكن لأجل أن هذا الأمر إبلاغ عن الله ﷻ، وكذلك فإن كلام النبي ﷺ ليس نطقًا عن الهوى قال ﷻ: ﴿وَمَا يَنْطِقُ عَنِ الْهَوَى * إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى﴾، فإذا أمر بأمر فقد أمر الله بطاعته فقال ﷻ: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ﴾ وغيرها من الآيات، فقد ألزم الله المؤمنين بطاعة النبي ﷺ وهذا ليس فيه نزاع بين المسلمين في وجوب طاعة النبي ﷺ.` },
      { q: `جواز الاجتهاد للنبي ﷺ ووقوعه منه فيما لم يرد فيه نص`, p: `97`,
        n: `وفيه دليل على جواز الاجتهاد للنبي ﷺ فيما لم يرد فيه نص من الله تعالى، وهذا مذهب أكثر الفقهاء وأصحاب الأصول، وهو الصحيح المختار. وفيه بيان ما كان عليه النبي ﷺ من الرفق بأمته ﷺ.`,
        o: NO_O,
        s: `فإن النبي ﷺ جعل يجتهد أيهما أرفق بالأمة، هل آمرها بالأمر المستحب الذي لهم فيه ثواب عظيم أم أن ذلك فيه مشقة عليهم؟ قال: (لولا أن أشق) حتى وصل الأمر أنه لا يريد أن يشق. هذا الحديث يدل على جواز الاجتهاد ووقوعه للنبي ﷺ؛ لأن الجواز أمر عقلي فقط، فقد يجوز له ولم يعمله ولذلك قلنا [ووقوعه]، مثل بعض الفقهاء يقولون: (يجوز له الاجتهاد ولكن لم يقع منه ولم يتكلم إلا بوحي)، والصحيح أنه تكلم بالاجتهاد ولكن اجتهاد النبي ﷺ يختلف عن اجتهاد غيره لأنه لا يقر على خطأ فأصبح اجتهاد النبي ﷺ سواء نزل الوحي بموافقته أو نزل الوحي بمخالفته فيتنزل الوحي بالبيان الصحيح والوجه فيها أو نزل الوحي بتقليله فيصبح هذا الأمر وحيًا، فأي أمر اجتهد فيه النبي ﷺ ثم غيره ورجع عنه فليس بمشروع، وأما إذا اجتهد ﷺ فسكت الوحي عنه فأقره فدل ذلك على أنه صار مشروعًا كذلك، فكل ذلك يدل على لزوم اجتهاده ﷺ وليس لأحد أن يجتهد بعد اجتهاده ﷺ؛ فكما ذكرنا فهو وحي في النهاية (وما ينطق عن الهوى إن هو إلا وحي يوحى) تنطبق على الأمور الاجتهادية أيضًا وذلك بالتقرير فالوحي أقره على ذلك فصار شرعًا.` },
      { q: `معنى التهجد: هل يشترط أن يكون بعد نوم؟ وأفضل وقت القيام`, p: `98`,
        n: `أما التهجد فهو الصلاة في الليل، ويقال: هجد الرجل إذا نام، وتهجد إذا خرج من الهجود وهو النوم بالصلاة، كما يقال: تحنث وتأثم وتحرج إذا اجتنب الحنث والإثم والحرج.`,
        o: `بعض العلماء: التهجد لا بد أن يكون بعد نوم.`,
        s: `بعض العلماء يقولون التهجد لا بد وأن يكون بعد نوم، وظاهر تعريف النووي أنه لا يلزم ذلك فقال: (أما التهجد فهو الصلاة في الليل) فليس بلازم لكي يتهجد الناس في رمضان أن تنام أولًا، بل يحصل لهم أن تهجدوا بأن تركوا النوم، مثل (تحنث) لا يلزم منها أنه لا بد وأن يقع في الحنث أولًا ثم يتركه مثل [تحرج وتأثم] فلا يعني أنه يقع في الإثم ثم يتركه، فلا يلزم ذلك فيمكن أن يكون ابتداء، ولذا تهجد يمكن أن تكون ابتداء قبل النوم فيترك النوم ابتداء ويصلي من الليل؛ لأن البعض يشترط فيقول لا بد وأن يقوم من نوم، لا بل يمكن أن يكون ذلك ابتداء قبل أن ينام. فيقولون صلاة التهجد في رمضان، فهل الصلاة الأولى (التراويح) أليست تهجد؟ هي تهجد، وصلاة الثانية أليست قيام هي قيام أيضًا؟ فكل هذه أسماء لمسميات واحدة، وهو ترك النوم للصلاة، فإذا قام من الليل وتهجد من الليل، فكل ذلك كله صحيح. استحب السلف أن ينام الرجل بعض الليل ويقوم بعض الليل، وأن آخر الليل أفضل والاستغفار بالسحر أفضل، ولا يستحب له أن يقوم الليل كله إلا في العشر الأواخر؛ ولذلك يستحب له أن ينام في أول الليل أو وسطه ويستيقظ آخره فهذا هو الأفضل. ولكن هل يحصل التهجد والقيام من بعد العشاء مباشرة؟ نعم.`,
        f: [
          `(ص99) على معاني الشوص (دلك الأسنان بالسواك عرضًا، وقيل الغسل، وقيل التنقية، وقيل الحك): وهذا هو الأظهر (الحك) وهو حك الفم ويحصل منه التنقية. والذي هو (دلك الأسنان بالسواك عرضًا) — أظهرها.`,
        ] },
      { q: `قراءة آيات آل عمران والنظر إلى السماء عند الاستيقاظ من الليل، والسواك قبل الوضوء`, p: `99–100`,
        n: `فيه أنه يستحب قراءتها عند الاستيقاظ في الليل مع النظر إلى السماء لما في ذلك من عظيم التدبر، وإذا تكرر نومه واستيقاظه وخروجه استحب تكريره قراءة هذه الآيات كما ذكر في الحديث.`,
        o: NO_O,
        s: `فسنة النظر إلى السماء للتفكر والتدبر سنة تكاد تكون مهجورة إلا من رحم الله ﷻ، وأنه يخرج من البيت ويرجع إلى البيت وهو ينظر إلى السماء. والقراءة تكون عند الاستيقاظ من الليل، فهناك بعض الروايات تقول (حتى ختم السورة) وهنا في مسلم (حتى بلغ فقنا عذاب النار)، وهذا وارد على التكرار فإن النبي ﷺ قد فعل ذلك ثلاث مرات، فقد يكون قد فعل ذلك أحيانًا وفعل ذلك أحيانًا، فما تيسر من ذلك فعل، ومع التدبر فيها (فويل لمن قرأها ولم يتدبرها). وهذا الحديث فيه: أنه تسوك وتوضأ وبدأ بالسواك قبل الوضوء فإنه (ثم رجع إلى البيت فتسوك وتوضأ) وهذا دليل على الترتيب مع التعقيب، فدل ذلك على مشروعية السواك قبل الوضوء، وإذا كانت الصلاة عقبه فلا يحتاج إلى تجديد التسوك. وهو قد بات عند النبي ﷺ عند خالته ميمونة كما هو معلوم وكما سيأتي إن شاء الله.` },
    ],
  },
  {
    title: `باب خصال الفطرة (ص100–116)`,
    items: [
      { q: `خصال الفطرة: هل هي واجبة؟ وما الواجب منها؟`, p: `101–102`,
        n: `أما قوله ﷺ «الفطرة خمس» فمعناه خمس من الفطرة كما في الرواية الأخرى «عشر من الفطرة» وليست منحصرة في العشر، وقد أشار ﷺ إلى عدم انحصارها فيها بقوله «من الفطرة». وأما الفطرة فقد اختلف في المراد بها هنا: فقال أبو سليمان الخطابي: ذهب أكثر العلماء إلى أنها السنة، وكذا ذكره جماعة غير الخطابي قالوا: ومعناه أنها من سنن الأنبياء صلوات الله وسلامه عليهم، وقيل: هي الدين. ثم إن معظم هذه الخصال ليست بواجبة عند العلماء، وفي بعضها خلاف في وجوبه كالختان والمضمضة والاستنشاق، ولا يمتنع قرن الواجب بغيره كما قال الله تعالى: ﴿كُلُوا مِنْ ثَمَرِهِ إِذَا أَثْمَرَ وَآتُوا حَقَّهُ يَوْمَ حَصَادِهِ﴾ والإيتاء واجب والأكل ليس بواجب.`,
        o: NO_O,
        s: `فهناك أشياء متفق على وجوبها فعلى سبيل المثال (الاستنجاء) مثلًا، فلم يقل عالم بعدم وجوبه، والصحيح بل الصواب أن إعفاء اللحية أيضًا من الواجبات وكذا قص الشارب، والسواك ليس فيه خلاف في أنه مستحب، والمضمضة والاستنشاق فيها خلاف. (والإيتاء واجب) أي إيتاء الزكاة واجب والأكل ليس بواجب.` },
      { q: `حكم الختان للرجال والنساء، والقدر الواجب منه`, p: `102–103`,
        n: `فالختان واجب عند الشافعي وكثير من العلماء، وسنة عند مالك وأكثر العلماء، وهو عند الشافعي واجب على الرجال والنساء جميعًا. ثم إن الواجب في الرجل أن يقطع جميع الجلدة التي تغطي الحشفة حتى ينكشف جميع الحشفة، وفي المرأة يجب قطع أدنى جزء من الجلدة التي في أعلى الفرج.`,
        o: `مالك وأكثر العلماء: الختان سنة. والشافعي: واجب على الرجال والنساء.`,
        s: `(الحشفة هي رأس الذكر) فالختان الذي يفعله البعض بترك جزء من الجلدة فهذا ختان ناقص، والواجب قطع جميع الجلدة. والصحيح أن الختان واجب على الرجال لأن النبي ﷺ قال: «ألق عنك شعر الكفر واختتن» (د 356) [قال الألباني: حسن] فأمره والأمر يدل على الوجوب (واختتن). وأما المرأة: فإن فوق فتحة خروج البول هناك قطعة جلد تشبه الذكر عند الرجل، وهو ذكر ضامر لدى الأنثى، أي أن هذا هو العضو الذي صار ذكرًا عند الرجل؛ فإن تكوين الإنسان جنين في بطن أمه الأعضاء تكون متقاربة مدة طويلة، فقطع هذا العضو أدنى جزء منه وهو جزء صغير جدًّا، ونحن لم نقل بأنه واجب على النساء لأن أحاديث خمس من الفطرة وعشر من الفطرة لا يدل على الوجوب بمجرده لأنه ليس أمرًا، وإنما ورد الأمر في الرجال بقوله: («ألق عنك شعر الكفر واختتن») وقد أسلمت كثير جدًّا من النساء ولم تؤمر بالختان. ومشروعية الختان للرجال والنساء ليس محل نزاع بين العلماء، والخلاف بينهم بين الوجوب والاستحباب، فقوله ﷺ: («خمس من الفطرة الختان») فهو حاصل للنساء بلا نزاع أيضًا؛ فالخلاف في أنه مستحب فقط، فالزاعمون أن الختان في النساء ليس من الدين أهل بدعة وضلال، وهذا إنكار للمتفق عليه بين العلماء، فلا يوجد عالم يقول أن ختان المرأة غير مشروع، وإنما الخلاف في الوجوب والصحيح عدم الوجوب، ولكن لا يقال أنه غير مشروع أو أنه مكروه أو أنه ليس من الدين فهذا إنكار لما عُلم من سنته ﷺ فيكون بدعة ضلالة، والدعوة إلى عدم ختن النساء أيضًا من البدع المنكرة، ووجود ضرر من مخالفة السنة في الختان وهو قطع زيادة على المشروع وهو قوله ﷺ: («أشمي ولا تنهكي») أي لا تستوعب القطع واستيعاب القطع لهذا العضو هو الذي قد يضر بالمرأة فيؤدي إلى البرود الجنسي والذي يؤدي إلى عدم دوام العشرة الطيبة بينها وبين الزوج، فهذا الأمر مجاوزة المشروع فيه هو السبب، وليس أن المشروع هو السبب حتى يُقال أن هذا الأمر يؤدي إلى الأضرار ويؤدي إلى فشل الحياة الزوجية فيما بعد، أما الالتزام بما أمر به النبي ﷺ من الإشمام وهو قطع جزء صغير من هذا العضو لم يضر بل يكون من أسباب عفة المرأة وأحظى عند الزوج؛ لأن هذا العضو عند بعض النساء يكون نموه كبيرًا ويكون من أسباب شدة الغلمة — أي الشهوة — فيترتب على ذلك بعض المفاسد، وأحيانًا كما ذكرنا لا يكون هناك حاجة لعدم نموه نموًّا طويلًا، فقطع أدنى جزء منه يكون مجزئًا.` },
      { q: `وقت الختان: الوجوب قبل البلوغ، والختان يوم السابع، وحساب يوم الولادة من السبع (وأثره في العقيقة)`, p: `103`,
        n: `والصحيح من مذهبنا الذي عليه جمهور أصحابنا أن الختان جائز في حال الصغر ليس بواجب، ولنا وجه أنه يجب على الولي أن يختن الصغير قبل بلوغه، ووجه أنه يحرم ختانه قبل عشر سنين. وإذا قلنا بالصحيح استحب أن يختن في اليوم السابع من ولادته. وهل يحسب يوم الولادة من السبع أم تكون سبعة سواه؟ فيه وجهان: أظهرهما يحسب.`,
        o: `وجه: يجب على الولي أن يختنه قبل بلوغه. ووجه: يحرم ختانه قبل عشر سنين.`,
        s: `كلا الوجهين ضعيف. واستحباب الختان يوم السابع بناء على حديث ضعيف فلا دليل على استحباب الختان يوم السابع. وأما حساب يوم الولادة فهذه الفائدة سوف تظهر في العقيقة، ولذلك لكي نحسب العقيقة متى نذبح العقيقة؟ فأظهر الوجهين وهو الصحيح أن أول يوم هو يوم الولادة، فإذا ولد قبل المغرب حسب ذلك اليوم، وإذا ولد بعد المغرب فهو من ليلة اليوم الذي يليه، فلو ولد بعد المغرب يوم الجمعة فيكون أول يوم له السبت وثاني يوم له يوم الأحد وبهذا ينبغي يوم الجمعة وهو اليوم السابع له، ولو ولد يوم الجمعة قبل المغرب فيذبح يوم الخميس. وظاهر الحديث وقول بعض الشافعية والظاهرية وجوب الاستحداد، ولكن الجمهور على الاستحباب. ويستحب ختان الأنثى قرب البلوغ؛ لأن الختان وهي صغيرة هو من أسباب التجاوز، فمن الناحية الطبية أن من أسباب التجاوز ومن أسباب عدم اكتمال القدر الواجب في ختان الصغير كذلك، فإذا اختتن وهو صغير جدًّا فيكون العضو صغيرًا فيترتب على ذلك عدم استيفاء القدر الواجب بالنسبة للذكر، والأنثى ينبغي أن تختن قرب البلوغ ولو بلغت ولم تختتن، شرع أن تختن ولو كانت امرأة كبيرة امتثالًا للسنة، فإن إبراهيم عليه السلام اختتن بالقدوم وهو ابن ثمانين سنة لما شرع الله ﷻ له الختان.` },
      { q: `ختان الخنثى المشكل، ومن له ذكران، ومن مات غير مختون`, p: `103–104`,
        n: `واختلف أصحابنا في الخنثى المشكل: فقيل: يجب ختانه في فرجيه بعد البلوغ، وقيل: لا يجوز حتى يتبين، وهو الأظهر. وأما من له ذكران فإن كانا عاملين وجب ختانهما، وإن كان أحدهما عاملًا دون الآخر ختن العامل، وفيما يعتبر العمل به وجهان: أحدهما بالبول، والآخر بالجماع. ولو مات إنسان غير مختون ففيه ثلاثة أوجه لأصحابنا: الصحيح المشهور: أنه لا يختن صغيرًا كان أو كبيرًا، والثاني: يختن، والثالث: يختن الكبير دون الصغير.`,
        o: `قيل: يجب ختان الخنثى في فرجيه بعد البلوغ. ووجهان آخران في الميت: يختن، أو يختن الكبير دون الصغير.`,
        s: `(لا يجوز حتى يتبين) وهذا هو الصحيح؛ لأنه لو تبين أنه ذكر فقطع جزء من الجلدة التي تشبه الذكر عند الأنثى والتي هي موضع الختان عند الأنثى، فيترتب على ذلك أنه قد قطع عضو الذكورة ففيه دية من أجل العيب الذي فيه، وكذا في الأنثى، فالصحيح أنه لا يجوز ختانه حتى يتبين. ومن له ذكران: وهذه من الفروض النادرة. والميت: الصحيح أنه لا يختن صغيرًا كان أو كبيرًا؛ لأن التكليف له أو لوليه وقد فات وقت التكليف. فلو قال النبي ﷺ: (اختتنوا) لقلنا بالوجوب فليس عندنا هنا لفظ عام؟ ولكنه قال: (واختتن) فكان خطابًا لرجل وهي واقعة عين، فالأصل أنها لا تعمم إلا إذا كان على مثل تلك الحال.` },
      { q: `الاستحداد (حلق العانة): حكمه ووسيلته والمراد بالعانة ووقته`, p: `104`,
        n: `وأما الاستحداد فهو حلق العانة، سمي استحدادًا لاستعمال الحديدة وهي الموسى، وهو سنة، والمراد به نظافة ذلك الموضع، والأفضل فيه الحلق، ويجوز بالقص والنتف والنورة. والمراد بالعانة الشعر الذي فوق ذكر الرجل وحواليه، وكذلك الشعر الذي حوالي فرج المرأة، ونقل عن أبي العباس بن سريج أنه الشعر النابت حول حلقة الدبر، فيحصل من مجموع هذا استحباب حلق جميع ما على القبل والدبر وحولهما. وأما وقت حلقه فالمختار أنه يضبط بالحاجة وطوله، فإذا طال حلق، وكذلك الضبط في قص الشارب ونتف الإبط وتقليم الأظفار. وأما حديث أنس (وقت لنا في قص الشارب ... أن لا نترك أكثر من أربعين ليلة) فمعناه لا نترك تركًا نتجاوز به أربعين لا أنهم وقت لهم الترك أربعين.`,
        o: NO_O,
        s: `(وهو سنة) وهو لم يذكر الخلاف فيه، والمشهور أنه سنة وهو قول الجمهور. و(النورة) وهو كاستعمال مادة كالكريم المزيل للشعر. والمشهور في العانة أنه الشعر الذي فوق ذكر الرجل وحواليه، وكذلك الشعر الذي حوالي فرج المرأة. وأما التوقيت: بمعنى أنه لا يلزم أن يترك الحلق أربعين يومًا فلا يقص أظافره ولا يحلق العانة، ولكن على حسب الحاجة وهو الصحيح ولكن لا يتجاوز الأربعين، و(وقت لنا) هو من أدلة الوجوب.` },
      { q: `تقليم الأظفار وكيفية البدء فيه`, p: `105`,
        n: `وأما تقليم الأظفار فسنة ليس بواجب، وهو تفعيل من القلم وهو القطع، ويستحب أن يبدأ باليدين قبل الرجلين فيبدأ بمسبحة يده اليمنى ثم الوسطى ثم البنصر ثم الخنصر ثم الإبهام ثم يعود إلى اليسرى فيبدأ بخنصرها ثم ببنصرها إلى آخرها ثم يعود إلى الرجلين اليمنى فيبدأ بخنصرها ويختم بخنصر اليسرى.`,
        o: NO_O,
        s: `لا دليل على ذلك وهي مسألة البدء بالمسبحة، وهو كلام الغزالي بلا دليل وكلهم تبعوا الغزالي في ذلك؛ ويحتمل البدء بخنصر اليمنى من باب البدء باليمين، والبدء باليد تكريمًا، ولكن البدء بمسبحة يده اليمنى ثم الوسطى فهذا الكلام لا نعلم دليلًا عليه.` },
      { q: `نتف الإبط وقص الشارب: حكمهما ومن يتولاهما، وهل يوكل غيره؟`, p: `105`,
        n: `وأما نتف الإبط فسنة بالاتفاق، والأفضل فيه النتف لمن قوي عليه، ويحصل أيضًا بالحلق وبالنورة. ويستحب أن يبدأ بالإبط الأيمن. وأما قص الشارب فسنة أيضًا، ويستحب أن يبدأ بالجانب الأيمن، وهو مخير بين القص بنفسه وبين أن يولي ذلك غيره لحصول المقصود من غير هتك مروءة ولا حرمة بخلاف الإبط والعانة.`,
        o: NO_O,
        s: `فليس من المروءة أن يجعل غيره ينتف إبطه، وأما حلق العانة فمحرم لأنه كشف عورة، إلا أن يجعل زوجته أو أمته.` },
      { q: `حد ما يُقص من الشارب: الإحفاء والحلق والاستئصال أم القص؟`, p: `105، 116`,
        n: `وأما حد ما يقصه فالمختار أنه يقص حتى يبدو طرف الشفة ولا يحفه من أصله، وأما روايات (أحفوا الشوارب) فمعناها: أحفوا ما طال على الشفتين. ... قال القاضي: وأما الشارب فذهب كثير من السلف إلى استئصاله وحلقه بظاهر قوله ﷺ: «أحفوا وانهكوا»، وهو قول الكوفيين. وذهب كثير منهم إلى منع الحلق والاستئصال، وقاله مالك وكان يرى حلقه مثلة ويأمر بأدب فاعله، وكان يكره أن يؤخذ من أعلاه، ويذهب هؤلاء إلى أن الإحفاء والجز والقص بمعنى واحد وهو الأخذ منه حتى يبدو طرف الشفة. وذهب بعض العلماء إلى التخيير بين الأمرين. هذا آخر كلام القاضي. والمختار في الشارب ترك الاستئصال والاقتصار على ما يبدو به طرف الشفة.`,
        o: `كثير من السلف والكوفيون: استئصاله وحلقه. ومالك: يمنع الحلق ويراه مثلة.`,
        s: `الظاهر التخيير ما بين أن يقص الشارب حتى يجزه (جزوا الشوارب) ولكن لا يحلقه وهو المبالغة في القص، وبين قص ما طال عن الشفة. في الحقيقة أن الحلق لم يرد في أي رواية من الروايات (القص والإحفاء والجز) وهو كلها المبالغة في القص، فأي ما كان فإنه مهما بالغ في القص لا يصل إلى الحلق، فالصحيح أن حلق الشارب لا يُشرع، وأما المبالغة في القص فهو أحد الوجوه الواردة فهو مخير بين المبالغة في القص (الجز) وبين قص ما زاد عن الشفة (حتى يبدو طرف الشفة) كل ذلك مشروع، فحلقه أو تركه حتى ينزل على الشفة فهو ممنوع. وقول بعض العلماء بالتخيير بين الأمرين هو الصحيح، وهو التخيير ما بين الجز وبين أن يأخذ من أسفله حتى يبدو طرف الشفة، ولكن ليس الحلق والاستئصال.` },
      { q: `إعفاء اللحية وخصالها المكروهة (الخضاب بالسواد والصفرة، والتبييض، والنتف، والتصفيف، والزيادة والنقص، والعقد)`, p: `105–107`,
        n: `وأما (إعفاء اللحية) فمعناه توفيرها وهو معنى (أوفوا اللحى) في الرواية الأخرى، وكان من عادة الفرس قص اللحية فنهى الشرع عن ذلك، وقد ذكر العلماء في اللحية عشر خصال مكروهة بعضها أشد قبحًا من بعض: إحداها: خضابها بالسواد لا لغرض الجهاد. الثانية: خضابها بالصفرة تشبيهًا بالصالحين لا لاتباع السنة. الثالثة: تبييضها بالكبريت أو غيره استعجالًا للشيخوخة لأجل الرياسة والتعظيم وإيهام أنه من المشايخ. الرابعة: نتفها أو حلقها أول طلوعها إيثارًا للمرودة وحسن الصورة. الخامسة: نتف الشيب. السادسة: تصفيفها طاقة فوق طاقة تصنعًا لتستحسنه النساء وغيرهن. السابعة: الزيادة فيها والنقص منها بالزيادة في شعر العذار من الصدغين أو أخذ بعض العذار في حلق الرأس ونتف جانبي العنفقة وغير ذلك. الثامنة: تسريحها تصنعًا لأجل الناس. التاسعة: تركها شعثة ملبدة إظهارًا للزهادة وقلة المبالاة بنفسه. العاشرة: النظر إلى سوادها وبياضها إعجابًا وخيلاء وغرة بالشباب وفخرًا بالمشيب وتطاولًا على الشباب. الحادية عشرة: عقدها وضفرها. الثانية عشرة: حلقها إلا إذا نبت للمرأة لحية فيستحب لها حلقها.`,
        o: NO_O,
        s: `المقصود بالكراهة الكراهة الشرعية وليس الاصطلاحية، ومن هنا سقط بعض المتأخرين في القول بأن اللحية حلقها مكروه فقط أخذًا بكلام النووي فحملوه على الكراهة الاصطلاحية، والذي يتأمل كلامه يجزم بأنه ما قصد إلا الكراهة الشرعية التي تشتمل على التحريمية والتنزيهية؛ فمنها ما هو من الرياء والكبر المحرم اتفاقًا حيث ذكر مثلًا: (خضابها بالسواد)، وكذلك من هذه الخصال (استعجالًا للشيخوخة لأجل الرياسة والتعظيم)، وكذلك (التصفيف ليستحسنه النساء)، وكذلك من الرياء (تركها شعثة إظهارًا للزهادة وقلة المبالاة)، و(النظر إلى سوادها إعجابًا وخيلاء وفخرًا بالمشيب وتطاولًا على الشباب)؛ فلا شك أن هذه الخصال محرمة بلا نزاع بين أحد من أهل العلم، ولذلك فإنه لو فعل ذلك بهذه النيات كان آثمًا، ومن هنا نقول أن عامة الخصال التي ذكرها خصال محرمة، ولذلك نقول أن المقصود هنا بالكراهة الكراهة الشرعية على اصطلاح الكتاب والسنة، فإن المكروه في الكتاب والسنة لا يستلزم الكراهة الاصطلاحية فهو يشملها وربما كان يقصد به التحريمية بل عامة كلام السلف في الكراهة غالبًا أنهم يستعملون ذلك في (أكره كذا) يستخدمونه بدلًا من أن يتلفظ بلفظ الحرام في موطن لم يرد نص المشرع فيه أنه حرام فيكرهون لفظ الحرام في غير ما ورد به النص، وإنما مقصدهم الكراهة التحريمية كما ذكرنا في كثير من المواطن، فقد قال الله ﷻ بعد ما ذكر الشرك والقتل والزنى وأكل مال اليتيم قال: (كل ذلك كان سيئه عند ربك مكروهًا) فدل هذا على أن الكراهة في اصطلاح الكتاب والسنة تشمل كراهة تحريمية وتنزيهية. وخضابها بالصفرة من غير السواد اتباعًا للسنة مستحب، فإن النبي ﷺ نهى عن الخضاب بالسواد فعن جابر بن عبد الله قال: [أتي بأبي قحافة يوم فتح مكة ورأسه ولحيته كالثغامة بياضًا فقال رسول الله ﷺ: «غيروا هذا بشيء واجتنبوا السواد»] مسلم، ولا يستثنى إلا الجهاد، وعليه يحمل فعل بعض الصحابة بالخضاب بالسواد، كما أن الخيلاء محرم إلا أنه في الجهاد مباح من أجل إغاظة العدو، فإذا خضبها بالسواد ليغيظ أعداء الله ﷻ بقوة المجاهدين وأنهم في مقتبل أعمارهم وأنهم في شبابهم فذلك مشروع. والنتف والحلق أول الطلوع هذا أخص من الخصلة الثانية عشر وهي الحلق مطلقًا لأنه خصه بأول الطلوع فقط كما يفعل كثير من الشباب، وفي الحقيقة فإن الواقع حاليًا هو هذا النوع وليس أول الطلوع فقط بل استمرارًا إيثارًا للمرودة وهو ألا يكون للإنسان لحية، وهذا أمر منافي للرجولة للصغير أو للمرأة أما صورة الرجل فتنافي ذلك، وكثير من الشباب الآن يحلقها أول طلوعها استعجالًا لطلوعها كما أوهمهم البعض بذلك وهذا وهم طبي وواقعي، فهذا ليس له علاقة بكثرة الحلق، فإن تكرار حلق اللحية لا يؤدي إلى نباتها، فنبات اللحية متعلق بأمور وراثية وهرمونية تؤدي إلى خلق الله لها، فأيضًا هو من المحرمات فيحلقها أول طلوعها لسرعة إنباتها وكذلك إيثارًا للمرودة وحسن الصورة. ونتف الشيب: وذلك لما ثبت من النهي عن نتف الشيب مطلقًا من اللحية ومن الرأس، فعن عمرو بن شعيب عن أبيه عن جده قال: قال رسول الله ﷺ: «لا تنتفوا الشيب، ما من مسلم يشيب شيبة في الإسلام — قال عن سفيان — إلا كانت له نورًا يوم القيامة» وقال في حديث يحيى: «إلا كتب الله له بها حسنة وحط عنه بها خطيئة» (د 4202) [قال الألباني: حسن صحيح]، وذلك فإنه يستحب تغييره لا نتفه؛ فظاهر أحاديث نهي النتف التحريم والجمهور ينص على الكراهة ولا أدري ما الصارف. والتصفيف: النية الخبيثة هي التي حرمت ذلك. والزيادة والنقص: الصدغ هو ما كان فوق العظمة التي أمام صماخ الأذن، والعذار ما تحتها وتسميه الناس الأطاط، فيطيل شعر الصدغ ثم يدخله في اللحية، أو أخذ بعض العذار مع حلق الرأس، فهذا من النقص من اللحية، وظاهر الأدلة تحريمه لأنه ينافي الإعفاء. ونتف جانبي العنفقة: وهو الشعر الذي في أسفل الشفة السفلى، فينتفه أو يحدده كما يفعل كثير من الخليجيين، وبعض المنتسبين للالتزام في بلادنا يحلق العنفقة بالكلية، ومثلها الأخذ من الشعر الذي على الخد، فيحلقه أو يزيله ليسوي اللحية، فالصحيح أن هذا كله من المحرمات لأنه ينافي التوفير والإعفاء وهو جزء من اللحية، وأما الأخذ من الطول والعرض فلم يذكره ضمن المكروهات وسيأتي الكلام عليها إن شاء الله. وتركها شعثة ملبدة (شعثة أي غير مصففة؛ ملبدة أي بعضها ملتصق ببعض)؛ وأدلة تحريم كل هذه الأمور هي أدلة تحريم الرياء والكبر والإعجاب بالنفس ونحو ذلك. وعقدها وضفرها: لقوله ﷺ: «يا رويفع لعل الحياة ستطول بك بعدي فأخبر الناس أنه من عقد لحيته أو تقلد وترًا أو استنجى برجيع دابة أو عظم فإن محمدًا ﷺ منه بريء» (س 5067) [قال الألباني: صحيح]، فعقد اللحية منهي عنه لأنه كان فعل أهل الشرك، والتضفير لأنه تشبه بالنساء ولأنه مثل العقد.` },
      { q: `حكم حلق اللحية، وحلق المرأة لحيتها إذا نبتت`, p: `108–109`,
        n: `الثانية عشرة: حلقها إلا إذا نبت للمرأة لحية فيستحب لها حلقها.`,
        o: `بعض المتأخرين: حلق اللحية مكروه فقط (حملًا لكلام النووي على الكراهة الاصطلاحية). والطبري: لا تغير المرأة لحيتها (لا تغيير لخلق الله).`,
        s: `والحلق مطلقًا سواء في أول النبت أو غيره محرم عند الأئمة الأربعة وغيرهم، ومن نقل من المتأخرين الكراهة فقد ذكرنا أن المقصود الكراهة الشرعية لا الاصطلاحية وهي كراهة التحريم لأنهم ينصون على حرمة حلقها وحرمة قصها كذلك إذا بالغ في القص حتى نافى الإعفاء، أما الأخذ من الطول والعرض فسيأتي؛ فالقص الشديد الذي ينافي التوفير والإعفاء فهو محرم وأيضًا من عادة الفرس والتشبه بهم محرم بالإضافة إلى أنه تغيير لخلق الله بالإضافة إلى أنه تشبه بالنساء، وقد دلت الأدلة على غلظ تحريم ذلك فتحريم حلق اللحية مأخوذ من منافاة الأمر الذي هو للوجوب على ظاهره وقد قال به عامة العلماء، ومأخوذ من أن حلق اللحية تشبه بالكفار وهو محرم بل ملعون من فعله، ومأخوذ من أنه تشبه بالنساء وملعون من فعله، مأخوذ كذلك من أنه تغيير لخلق الله لم يأذن به الله وقد قال ﷻ عن الشيطان: (فليغيرن خلق الله)، وقد ذكر العلماء أن في اللحية إذا جنى عليها جانٍ فصارت لا تنبت بعد ذلك الدية كاملة، فمن اعتدى على لحية إنسان أحرقها مثلًا حتى احترق الجلد فأصبح لا تنبت له لحية فقد ذكر العلماء أن فيها الدية لأنه عضو مقصود ولا يوجد ما يناظره ففيه الدية كاملة (مائة من الإبل) وهذا في الجناية عليها بحيث لا تنبت مرة ثانية، أما الاعتداء بالحلق فقط فليس فيها الدية فهي جناية ولكن ليس فيها دية إلا إذا لم تنبت مرة ثانية. وهناك وجه بوجوب حلق اللحية للمرأة لحرمة التشبه بالرجال وكذلك الشارب، فالمرأة تؤمر بحلق اللحية استحبابًا أو وجوبًا بتغيير اللحية إذا ظهرت بإزالتها لأن تركها تشبه بالرجال فتزيله مثل إزالة شعر العانة والإبط فإنه شعر مأذون في إزالته وكذلك في إزالة شعر اللحية خلافًا للطبري فيقول (تترك على حالها لأن هذا تغيير لخلق الله)، والذي يظهر أن هنا يتعارض عمومين: عموم النهي عن التغيير وعموم النهي عن التشبه بالرجال، والأظهر تقديم عموم النهي عن التشبه بالرجال لأنه ليس له ما يخصصه، أما التغيير فقد ورد ما أذن في التغيير فيه مثل إزالة شعر الإبط والعانة كما ذكرنا وتغيير الشيب فهذا مشروع مستحب أو واجب على قول البعض ومن هنا نقول أن العموم غير المخصوص مقدم على العموم المخصوص، فلم يرد دليل على تخصيص عموم النهي عن التشبه بالرجال فهذا غير مخصص. فإن التشبه هو قصد حصول الشبه وقد يشمل عدم تغيير ما خلقه الله فينا كما قال (غيروا الشيب لا تشبهوا باليهود)؛ وهذا الأمر لا يدخل فيه الأمر المشترك بين الرجال والنساء فهذا لا يسمى تشبهًا. نعود للمسألة أن العموم الغير مخصص مقدم على العموم المخصص لأن العموم بعد تخصيصه نوع من المجاز أو خلاف الظاهر فبقاؤه على عمومه نوع من المجاز، بل إن بعض العلماء يرى عدم صحة الاحتجاج بالعام بعد تخصيصه فيقولون العام الذي خصص تبين أنه ليس بعام، والراجح الذي عليه جماهير الأصوليين أن العام بعد تخصيصه يحتج به على عمومه فيما عدا المخصص، فيكون بمنزلة الاستثناء تمامًا، فاللفظ العام إذا خصص منه بعض الأفراد فهو باقٍ على عمومه وإن كان المخالفة في الظاهر في الجزء الذي ورد فقط، ولكن قد ضعفت دلالة العموم فيه، ولذلك نرجح (النهي عن التشبه النساء بالرجال) على (النهي عن تغيير خلق الله) ولذلك قال جمهور العلماء بمشروعية حلق المرأة لحيتها إذا نبتت وشاربها والله أعلى وأعلم. وباقي شعور البدن كالحاجبين فمعلوم النهي عن النمص وهو للنساء مع حاجتهن للتزين ومع ذلك ورد اللعن في ذلك والرجال أشد، وعمومًا شعر الوجه بالنسبة للرجل لا يجوز إزالته وهو داخل في اللحية لأن الشعر الذي على الخد هو داخل في اللحية، أما الأذنين فمن الرأس؛ فباقي شعور البدن عمومًا يجوز إزالتها فلم يرد فيها تحريم والله أعلى وأعلم؛ إلا ما كان من نيات خبيثة في ذلك، كمن يزيل شعر البدن تصنعًا تشبهًا بالنساء فهذه النية محرمة، والشعر بين الحاجبين للنساء هو داخل في الحاجبين سواء اتصلوا أو لم يتصلوا هو من الحاجب.`,
        f: [
          `(ص108–109) السراويل للنساء: والسراويل والإزار من الثياب المشتركة بين الرجال والنساء وليس أن السراويل محرمة على النساء مطلقًا بزعم التشبه بل لا نعلم أحدًا من أهل العلم المتقدمين يقوله، فبعض المتأخرين يقوله من باب العادات ولكن هذا الأمر متفاوت جدًّا في الأمم والشعوب، فمن قصدت لبس السروال وليست من عادة قومها لبسه فقصدت بذلك التشبه بالرجال فهي المذمومة وأما إذا كانت تلبسه عمومًا فليس بذلك؛ لحديث عبد الله بن عمر: أنه سمع رسول الله ﷺ «نهى النساء في إحرامهن عن القفازين والنقاب وما مس الورس والزعفران من الثياب، ولتلبس بعد ذلك ما أحبت من ألوان الثياب معصفرًا أو خزًّا أو حليًّا أو سراويل أو قميصًا أو خفًّا» (د 1827) [قال الألباني: حسن صحيح]. والسروال إذا لبسته المرأة وكان سروالًا واسعًا لا يصف حجم عظامها ولا أعضائها جاز لبسه، لكن الواقع أن السراويل الموجودة سراويل ضيقة، ونقصد بالسروال الواسع من أوله إلى آخره بحيث لا يظهر أي تفصيل لعورة المرأة للأرداف ولا للفخذ ولا لأي شيء، ولذا فعلة التحريم في البناطيل الحديثة هي إظهار عورة المرأة وليس التشبه، فلما تكون سراويل مثل سراويل الرجل الصياد فهذا ليس بمحرم ولكن هذا ليس هو الموجود، فعلينا أن نبين الحكم فنقرره ونبين أن الذي يحدث بالقطع واليقين لا يجوز لباسها ولا حتى في المنزل أمام المحارم ولا حتى أمام النساء؛ فبناطيل الاسترتش والجنز الضيق والتي عمومًا تجسم العورة المغلظة والتي تجسم الفخذ والذي هو عورة عند الجميع حتى مع محارمها حتى مع النساء، فمن السرة إلى الركبة عورة المرأة مع المرأة، فمع أمها ومع أختها هذا من العورة باتفاق العلماء، فتجسيم العورة أمام المحارم أمر لا يجوز، كما لا يجوز للرجل أن يكشف أو يجسم عورته بالبناطيل الضيقة التي تجسم العورة المغلظة أمر لا يجوز، فالمرأة التي تلبس بنطلون يجسم الأرداف ويجسم الفخذ وربما يجسم القبل وأسفل البطن وما تحت السرة فهذا محرم بلا نزاع، فلا يقول عالم بجوازه بحال من الأحوال فهن من الكاسيات العاريات، فهذا هو الحكم الشرعي في هذا الباب؛ فنحن هنا نتكلم عن جزئية أن هذا تشبه أم لا، لأن كثيرًا من الفتاوى المعاصرة يقولون أن هذا من باب التشبه مطلقًا، وهذا الأمر فيه نظر والله أعلم، فهو محرم من باب التبرج.`,
        ] },
      { q: `حلق اللحية للضرورة والإكراه، والتشبه بالكفار في دار الكفر، وضوابط الإكراه (فوات الحاصل وامتناع المنتظر)`, p: `109–113`,
        n: NO_N,
        o: `من يحتج بكلام شيخ الإسلام ابن تيمية في أن المسلم في دار الكفر غير مأمور بمخالفتهم في الهدي الظاهر، على جواز حلق اللحية مطلقًا.`,
        s: `حلق اللحية إنما يجوز للضرورة، فعل حسب هذه الضرورة؛ فإنسان يضرب ضربًا شديدًا أو يحبس ويسجن، يجوع ويعرى، فرجل لا يجد عملًا لدرجة أنه يجوع أو يعرى وتظهر عورته فهذا الإنسان معذور فلا يكلف الله نفسًا إلا وسعها، فعفي عن أمتي الخطأ والنسيان وما استكرهوا عليه، فهذا الإنسان مكره، وضوابط الإكراه والضرورة هي التي تحكم في ذلك. أما كلام شيخ الإسلام ابن تيمية الذي يحتجون به في مسألة أن المسلم في دار الكفر غير مأمور بمخالفة وإنما يجوز له أن يتشبه بهم في الهدي الظاهر: [إنما يكون هذا في حال الخروج من دار الكفر إلى دار الإسلام (أثناء الخروج)] وليس أنه يبقى في دار الكفر أبدًا أو مستمرًا ناويًا الإقامة وفي نفس الوقت يقول أنه في دار الكفر فيطبق كلام شيخ الإسلام ابن تيمية في غير موضعه، ثم إن كلام شيخ الإسلام ابن تيمية ليس نص من الكتاب أو السنة وإنما هو مستنبط من أحوال معينة عندما يعجز الإنسان عن التخلص من أذى الكفار إلا من بمشابهتهم جاز له ذلك، فتطبيق الكلام على هذا الواقع غير صحيح، والأدلة على ذلك هي أدلة العجز عن فعل الواجبات أو أدلة الإكراه على فعل المحرمات وتطبيقها أن دار الكفر غالبًا ما يحصل بها ذلك، ولكن لو هناك دار كفر لا يحصل بها أي أذى للمسلم بإعفاء اللحية أو دار فسق لا يحصل له الأذى المعتبر شرعًا فلم يجز له أن يحلقها. ووصف ديار المسلمين اليوم بأنها دار كفر تطبيق الكلام عليه فيه نظر، فوجود بعض مظاهر الكفر في ديار المسلمين لا يعني أنها قد صارت دار كفر بالكلية لأن شعار الإسلام مازال ظاهرًا وأهلها مسلمون فهي فيها من معاني دار الكفر والفسق وفيها من معاني دار الإسلام، وهذا التقسيم تقسيم اصطلاحي وليس تقسيم شرعي ولذلك لا يلزم التزامه دائمًا، ولا يلزم تسمية الدار أنها إسلام أو كفر وحتى لو هي دار كفر ولم يحصل للمسلم ضرر معتبر بإقامة شعيرة من شعائر الإسلام وإظهارها لم يكن جائزًا له أن يتركها بأن تمكن من أن يؤذنوا ويصلوا جماعة في دار الكفر فعلوا ذلك وإذا تمكنوا من إقامة شعائر الدين بصفة عامة في أي مكان في الأرض فأرض الله واسعة، فالمطلوب عبادة الله (قل يا عبادي الذين آمنوا إن أرضي واسعة فإياي فاعبدون) فعبادة الله تكون في أي مكان في الأرض والأدلة عامة لم تخصص أرض دون أرض بعبادة معينة، فالواجب هو أن يعبد الله ﷻ بطاعته وطاعة رسوله ﷺ في كل مكان في العالم، فكون إنسان يحتج بكلام بعض العلماء الغير مقصود به تعميمه وليس كقاعدة كلية في أن كل شيء يتشبه بهم فهل يلبس الزنار مثلًا وهل يرفع الصلبان في ديار الكفر، إنما يفعل ذلك إذا كان مضطرًا بمعنى أنه مكره، سوف يقتلونه إن لم يفعل، فهو يتشبه بهم حتى يفر منهم، وليس أنه ليظل مقيمًا على الدوام والله أعلى وأعلم. فنقول في أمر حلق اللحية أو التشبه عمومًا بالكفار في الهدي الظاهر، إنما هو في حالة الضرورة حتى يتخلص من شرهم، وإلا فإن كان عاجزًا عن إقامة الدين في وسطهم وهو قادر على الهجرة، كان ذلك واجبًا عليه، فإذا كان أحد واجبات الدين يُلزم بتضييعه وهو قادر على إقامته في غير هذه الأرض وجب عليه أن يهاجر لإقامة واجب الدين، إلا أن يكون الشر في الأرض منتشرًا فيختار ما بين الشرور فيختار أقلها ويتحمله ليدفع أكثرها، ويحصل أكثر الخير ولو فات بعض الخير، وهذا باب الفتن المتكاثرة التي أمر الموازنة فيها التي دلت عليه أدلة الكتاب والسنة من مراعاة المصالح والمفاسد ومراعاة دفع أعظم المفسدتين لتحمل أدناهما وجلب أعظم المصلحتين ولو بتفويت أدناهما لأن الله لا يحب الفساد ولا يحب المفسدين والأنبياء يريدون الإصلاح ما استطاعوا قال شعيب: (إن أريد إلا الإصلاح ما استطعت) فالأمر بالصلاح والإصلاح وفعل ما هو الأصلح حتى ولو كان فيه تفويت بعض ما هو صالح هي الأوامر الشرعية عليها أدلة الكتاب والسنة كقاعدة كلية. نريد أن ننوه هنا على مسألة الإكراه في حلق اللحية خصوصًا وعمومًا فإن باب الإكراه معروف حدوده الشرعية وهو يكون بفوات حاصل للإنسان في نفسه وعرضه وماله وليس بخوف امتناع المنتظر إلا ما كان من حاجة شديدة لهذا المنتظر فيلحق بتفويت الحاصل (فحاصل الإنسان في نفسه بسلامة النفس والأعضاء والسلامة من الألم) فهذه الأمور إذا تعرضت للفوات بقتل أو ضرب أو تعذيب أو قطع عضو من الأعضاء أو حبس فذلك كله من الإكراه، إلا أنه قد يتفاوت بتفاوت المكره عليه، لكن الأصل فيها كلها أنها إكراه؛ فلو أنه يحبس إن أطلق لحيته جاز له أن يحلقها، وقلنا أنها تتفاوت بتفاوت المكره عليه لأن هناك اتفاق بين العلماء على أن الحبس ليس إكراهًا على الذمة، والمكره عليه فيما يتعلق بحقوق العباد لا يصح عليه إكراه فلا يصح أن يقتل مسلمًا أو ينتهك حرمته إلا ما كان من أمر المال [إفساد المال] فالراجح أنه يحتمل إفساد مال أخيه بإنقاذ نفسه هو لا لإنقاذ ماله لأن مال الأخ يجوز الإقدام عليه في حال الضرورة وذلك لإنقاذ نفسه بإفساد مال أخيه دون نفس أخيه أو عرضه فذلك جائز ولذلك نقل القرطبي قال: [أجمع العلماء على أن من أكره على قتل غيره أنه لا يجوز له الإقدام على قتله ولا انتهاك حرمته بجلد أو غيره، ويصبر على البلاء الذي نزل به، ولا يحل له أن يفدي نفسه بغيره، ويسأل الله العافية في الدنيا والآخرة] تفسير القرطبي (سورة النحل، آية 106)؛ وهذا هو المقصود في أن الإكراه يتفاوت بتفاوت المكره عليه؛ فبعض البلاد قد يكون الإنسان عاجزًا بالفعل عن أن يطلق لحيته ويغلب على الظن — وهو شرط من شروط الإكراه المعتبر شرعًا — وهو غلبة الظن بحصول العقاب وعدم القدرة على دفعه ولو بالفرار وأن يكون ما هدد به فوريًّا — وأما ما كان من أمد بعيد ليكتبوا له ملف أو تقرير من الممكن أن يقبض عليه في يوم من الأيام فمثل هذا ليس فوريًّا وبالتالي فلا يبيح للإنسان أن يحلق لحيته ولا أن يفعل المعصية عمومًا ولا أن يترك الجماعة مثلًا أو ترك طلب العلم الواجب عليه لأجل أنه إذا فعل ذلك أخذ في المستقبل فهذا أمر مظنون وليس مقطوع به ولا حتى يغلب على الظن ولا يلزم أن يكون كل واحد كذلك، ولكن غلبة الظن بأن يكثر جدًّا مثل أنه لو كل من سار في الطريق ملتحيًا قبض عليه، وكما ذكرنا يكون الإنسان عاجزًا عن التخلص ولو بالفرار. نعود إلى باقي ما يكره به، فقد قلنا أن القيد والحبس والضرب إكراه والتعذيب وقطع الأعضاء والقتل كل ذلك إكراه، وأخذ المال المجحف بالإنسان يعد نوعًا من الإكراه أيضًا ولكن ما يكره به يتفاوت ولكن يعد إكراه ابتداءً كهدم الدار وأخذ المال الكثير الذي يجحف بالإنسان أما أخذ الحبة من المال فالذي عليه المحققون والعلماء أن ذلك لا يعد إكراهًا والبعض يقول ولو قل، والراجح أن القليل لا يعد إكراهًا، وهذا الأمر مرده إلى العرف، وأما العرض فهو الجاه، وأما الاعتداء على العرض بالاصطلاح المعاصر والذي هو الاعتداء الجنسي فهذا ضمن الاعتداء على النفس، وأما الجاه فالمقصود به الإهانة أمام الناس فهذا هو الاعتداء على العرض، أما الاعتداء عليه جنسيًّا مثلًا أو على أهله أو ولده أو نحو ذلك، فذلك ضمن الاعتداء على النفس، بمعنى أنه يُنظر فيه فإن كان بأمر أغلظ منه فيجوز أن يستسلم لذلك وإلا لم يجز، بحيث لو قيل لو تقتل أنت أو ينتهك عرضه (أهله) فهذا هو الذي يبيح للإنسان للاستسلام ولو قاتل حتى قتل لكان شهيدًا، فالمقصود بزوال الجاه هو الإهانة مثل أن يوقف فيه حافيًا أو محلوقًا أو بلا غطاء رأس في العشائر ومثلها الآن أن يخرجوه بملابس النوم مقيدًا حافيًا مقبوضًا عليه يسب في الطريق، فهذا الأمر ليس مؤلمًا لليد أو للرجل أو للبدن بقدر ما هو مؤلم للنفس من جهة الوجاهة أمام الناس فهذا معدود إكراهًا عند العلماء، لكن كما ذكرنا أنه يتفاوت، فالإكراه المعتبر في قبول الهبة ليس كالإكراه المعتبر في النطق بكلمة الكفر، كأن قيل له أشرب كوب الليمون هذه أم نشتمك ونهينك مثلًا وبين أن يقال له نشتمك ونهينك أم تنطق بكلمة الكفر؛ مع أن شد الأذن متعلق بالبدن فإنه لا يجوز، فلا تنطق كلمة الكفر إلا عند التعذيب الشديد، لتفاوت هذا الأمر، فهذا الأمر محل اجتهاد ليقدم الإنسان جانب الدين ما استطاع، فالغرض المقصود في ذلك أن هذا كله من باب فوات الحاصل في هذه الأشياء. أما خوف امتناع المنتظر: وهو أنه إذا لم يفعل المعصية أو يترك الواجب لم يعطوه ما يريد، مثل مريض إذا لم يطع الطبيب في المعصية ما عالجه، فهو يتوقع الشفاء وليس الشفاء حاصلًا وسوف يفوت، بخلاف الذي يضرب ويعذب إلى أن يفسد عضو من أعضائه أو منفعة من منافعه، بخلاف مريض يتركه الطبيب لا يعالجه، فهذا الأمر ليس بإكراه إلا لو وصل لشدة الحاجة إليه إلى فوات الحاصل، مثل إنسان عنده مغص شديد جدًّا — مغص كلوي — فيتألم ألم شديد ومعلوم بغلبة الظن أن هناك دواء يسكن هذا الألم، فهو إذا لم يطع في ذلك من فعل المعصية أو ترك الواجب لم يأخذ هذا الأمر، مع شدة الحاجة إليه ومثلها الأكل والشرب وهذا في الحقيقة خوف امتناع منتظر بمعنى أنه لو لم يطعه لم يعطه يأكل، فابتداءً لا يجوز، ولكن لو وصل إلى حد أنه يجوع جوعًا شديدًا جدًّا ويخاف الهلاك فيقترب أو يلحق بفوات الحاصل، رغم أنه خوف امتناع منتظر، فهو شيء ليس موجودًا عنده، بخلاف عطشان وفي يده الماء ولو أخذوها منه سوف لا يجد الماء فهذا فوات حاصل، وأما لو هو عطشان والماء بيد الآخر وقال له إن لم تسمع الكلام وإلا لم نعطي لك الماء، وقد ورد في المرأة التي كانت في بادية وكانت في حالة عطش شديد فلم يسقها حتى تسلم نفسها فأسلمت نفسها، فأسقط نظن عمر ﵁ عنها الحد لأنها مكرهة فهي في صحراء وسوف تهلك إن لم تفعل فهي معذورة في مثل تلك الحالة، وهذا من إلحاق ما هو من خوف امتناع منتظر بفوات الحاصل. ومثال خوف امتناع منتظر بالنسبة لحلق اللحية التعيين في الوظائف، فالأصل أن الإنسان يبحث عن أي عمل لا يلزمه عمل معين يختاره لنفسه ولا يقبل غيره أو نحو ذلك، هذا الأمر الأصل فيه أنه من باب خوف امتناع منتظر لأنه في الحقيقة يقول له لو لم تحلق لم أعينك لكي تأخذ مال، فهو لم يأخذ ماله ولا سيسجنه ولكن يقول له لا أعينك، ولما يتعين سيأخذ المال، فلا شك أن هذا ليس إكراه ابتداءً، ولكن لو وصل الحال أنه يجوع ويعرى، فهذا قد يلحق بفوات الحاصل. والصبر على عدم فعل المعصية عند الإكراه له أجر عظيم، فلا يأثم بذلك، الضرورة التي تكلم العلماء عليها أنه يأثم كإنسان سوف لا يفعل المعصية ولكنه تناول المحرم فهو لم يباشر فعل المعصية، ولذلك العلماء اتفقوا على أنه لو صبر فلم ينطق بكلمة الكفر حتى قتل فله أجر عظيم والدليل على ذلك فعل بلال ﵁، فصبر بلال ونطق عمار ﵁، فنطق عمار يدل على الرخصة وصبر بلال يدل على الفضيلة بأن يصبر ولا ينطق بكلمة الكفر، وكذلك قول عبد الله بن حذافة لما عرض عليه ملك الروم الخمر، قال: قد علمت أنه قد أحل لي، ولكن ما كنت لأشمتك بي، وذلك ليغيظ الكفار وهي نية صالحة، فكونه لا يأخذ بذلك، فهو مأجور إن شاء الله. وفتوى باحتجاج خروج المسلمين في جيوش الأمريكان احتجاجًا بأن العباس خرج مع جيوش الكفار في غزوة بدر، فتوى في غاية الضلال؛ فإن فعل العباس هذا كان من الكفر الذي قال له النبي ﷺ: (افد نفسك وابن أخيك)، أفيحل مال امرئ مسلم من غير طيبة من نفسه، أيحل أسر مسلم بغير حق، فالنبي ﷺ عامله معاملة الكفار، فقد قال له النبي ﷺ: (فأما ظاهرك فقد كان علينا، افد نفسك وابن أخيك)، فلم يقبل منه ﷺ ذلك، ونزل في ذلك قوله ﷻ: (إن الذين توفاهم الملائكة ظالمي أنفسهم قالوا فيم كنتم قالوا كنا مستضعفين في الأرض قالوا ألم تكن أرض الله واسعة فتهاجروا فيها فأولئك مأواهم جهنم وساءت مصيرًا) نزلت فيمن خرج ممن يحب الإسلام مع الكفار، فمن مات منهم مات كافرًا ومن أسر منهم عومل معاملة الكفار أيضًا ولم يقبل إسلامه في ذلك، فهذا حجة عليه وليس حجة له، ففعل العباس ﵁ من المخالفة للشرع وليس موافقًا للشرع والنبي ﷺ ما أقره بل عاقبه وأخذ ماله وقال عمر ﵁: أرى أن تدفع عقيلًا إلى علي فيقتله، فقد كان عمر ﵁ يرى أن هؤلاء الأسرى يقتلوا كلهم بما فيهم العباس وعقيل، وهؤلاء من بني هاشم خرجوا مراعاة لقومهم، وهذا قد يكون لولا ما سبق من فضل الله ورحمته بهم لمن أسلم منهم، ففتوى جواز القتال في صفوف الكفار فتوى كفر والعياذ بالله. فهذا لا يعد إكراهًا فالفصل من الوظيفة وعدم إعطائه راتبه فمن باب خوف امتناع منتظر، لأنه يقول له أنا سوف لا أجدد معك العقد الشهر القادم، فهذا لا يعد إكراهًا على حلق اللحية فضلًا أن يكون إكراهًا على الكفر من قتال أهل الإسلام وسفك دمائهم.` },
      { q: `غسل البراجم وما يلحق بها من الأوساخ، وما بين الأظفار من وسخ: هل يمنع صحة الوضوء؟`, p: `113`,
        n: `وأما (غسل البراجم) فسنة مستقلة ليست مختصة بالوضوء، والبراجم عقد الأصابع ومفاصلها كلها. قال العلماء: ويلحق بالبراجم ما يجتمع من الوسخ في معاطف الأذن وهو الصماخ فيزيله بالمسح، لأنه ربما أضرت كثرته بالسمع، وكذلك ما يجتمع في داخل الأنف، وكذلك جميع الوسخ المجتمع على أي موضع كان من البدن بالعرق والغبار ونحوهما.`,
        o: `بعض العلماء: الأوساخ إذا اجتمعت تحت الأظفار وصار لها جرم تمنع من صحة الوضوء.`,
        s: `ومثله ما بين الأظفار والجلد وخصوصًا في القدمين فيجتمع بعض الأتربة وكذلك تحت الأظفار، بعض العلماء يقول أن هذه الأوساخ إذا اجتمعت وصار لها جرم يمنع من صحة الوضوء، والراجح والله أعلم أن اليسير من ذلك كما يكون بين الأظفار من الطين المجتمع أو الوسخ المجتمع أن هذا مما يعفى عنه والله أعلم، لأن النبي ﷺ قال: (ما لي لا أهم ورفغ أحدكم بين أنملته وظفره؟!) قال الألباني: منكر [أخرجه البزار في «مسنده» (1/139/266)، والعقيلي في «ضعفائه» (2/212)، والطبراني في «معجمه» (10/228/10401) من طريق الضحاك بن زيد الأهوازي عن إسماعيل بن أبي خالد عن قيس بن أبي حازم عن عبد الله بن مسعود قالوا: يا رسول الله إنك تهم؟ قال: ... فذكره. وقال البزار: «لا نعلم أحدًا أسنده إلا الضحاك وروي عن قيس مرفوعًا ومرسلًا». وذكره العقيلي في ترجمة الضحاك هذا وقال: «يخالف في حديثه». وقال فيه ابن حبان في «الضعفاء» (1/379): «كان ممن يرفع المراسيل ويسند الموقوف، لا يجوز الاحتجاج به، لما أكثر منها»]. والرفغ وهو ما تحت الإبط، فأنكر عليهم ﷺ أن يأتوا على تلك الهيئة فأنكر عليهم ولم يأمرهم بإعادة الصلاة.` },
      { q: `توقيت خصال الفطرة «وقت لنا»، وحال جعفر بن سليمان الراوي`, p: `114`,
        n: `قوله (وقت لنا) هو من الأحاديث المرفوعة مثل قوله: أمرنا بكذا، وقد جاء في غير صحيح مسلم (وقت لنا رسول الله ﷺ). قال القاضي عياض: قال العقيلي: في حديث جعفر هذا نظر، قال: وقال أبو عمر — يعني ابن عبد البر —: لم يروه إلا جعفر بن سليمان وليس بحجة لسوء حفظه وكثرة غلطه. قلت: وقد وثق كثير من الأئمة المتقدمين جعفر بن سليمان، ويكفي في توثيقه احتجاج مسلم به، وقد تابعه غيره.`,
        o: `العقيلي وابن عبد البر: جعفر بن سليمان ليس بحجة لسوء حفظه.`,
        s: `فكونه سيئ الحفظ فهذه درجة من الدرجات اختلف فيها العلماء، فليس بالسيئ لدرجة رد الرواية فضلًا عن وجود المتابعات الكثيرة. و(وقت لنا) هو من أدلة الوجوب كما تقدم.` },
      { q: `الأخذ من طول اللحية وعرضها، وحده (ما زاد على القبضة)، والأخذ منها في الحج والعمرة`, p: `114–116`,
        n: `وأما (أوفوا) فهو بمعنى أعفوا أي اتركوها وافية كاملة لا تقصوها ... (وأرخوا) معناه اتركوها ولا تتعرضوا لها بتغيير ... وجاء في رواية البخاري (وفروا اللحى) فحصل خمس روايات: [أعفوا وأوفوا وأرخوا وأرجوا ووفروا]، ومعناها كلها: تركها على حالها، هذا هو الظاهر من الحديث الذي تقتضيه ألفاظه، وهو الذي قاله جماعة من أصحابنا وغيرهم من العلماء. وقال القاضي عياض رحمه الله تعالى: يكره حلقها وقصها وتحريقها، وأما الأخذ من طولها وعرضها فحسن، وتكره الشهرة في تعظيمها كما تكره في قصها وجزها. قال: وقد اختلف السلف هل لذلك حد؟ فمنهم من لم يحدد شيئًا في ذلك إلا أنه لا يتركها لحد الشهرة ويأخذ منها، وكره مالك طولها جدًّا، ومنهم من حدد بما زاد على القبضة فيزال، ومنهم من كره الأخذ منها إلا في حج أو عمرة. والمختار ترك اللحية على حالها وألا يتعرض لها بتقصير شيء أصلًا.`,
        o: `القاضي عياض: الأخذ من الطول والعرض حسن. وبعض السلف: يؤخذ ما زاد على القبضة. وبعضهم: يكره الأخذ منها إلا في حج أو عمرة. والنووي: المختار ترك اللحية على حالها. والشيخ الألباني: يوجب الأخذ منها في الحج والعمرة.`,
        s: `(«يكره»: المقصود الكراهة الشرعية كما ذكرنا. و«حد الشهرة»: فتطول حتى يقال فلان الذي لحيته طويلة.) فعل ابن عمر ﵁ في أخذ ما زاد عن القبضة وهو راوي حديث وفروا وأرخوا يدل على أن معنى وفروا وأرخوا ليس عدم الأخذ منها بالكلية بل تركها وفيرة كبيرة ولا يلزم من ذلك عدم الأخذ منها أصلًا كما يقول النووي رحمه الله. وفعل ابن عمر وغيره من السلف الأخذ منها في الحج والعمرة يدل على مشروعية الأخذ من الطول والعرض كما ذكر القاضي عياض ولكن يكون في ما زاد عن القبضة لأن هذا ما فعله ابن عمر فيكون حد القلة والكثرة ما زاد عن القبضة، ويشرع ذلك خصوصًا في الحج والعمرة من باب قضاء التفث كما فسره غير واحد من الصحابة والتابعين (ثم ليقضوا تفثهم وليوفوا نذورهم) الشيخ الألباني يوجب ذلك، ولكن هذا الوجوب فيه نظر، فلا نعلم أحدًا يقول بوجوبه والله أعلم إلا قول الشيخ الألباني، ولكن في غير ذلك فليس بمحرم. فنحن نقول فعل ابن عمر تفسير لمعنى وفروا وأرخوا، فالخلاف هنا في كلمة وفروا هل هي تقتضي عدم الأخذ بالكلية كما هو معناها اللغوي؟ وأما في اللحية فيتركها وإن أخذ ما زاد عن القبضة طولًا وعرضًا فلا يمنع، ويشرع ذلك في الحج والعمرة والله أعلم. فنقول مع ما كان عليه ابن عمر من شدة اتباعه للسنة في هذا الفعل وغيره، فعله هذا يدل على أن وفروا عندهم لا تدل على أن معناها الترك بالكلية ولكن التوفير أن تكون وافرة كبيرة كاملة وافية كل ذلك يحصل بوصولها إلى هذا الحد وهو كما ذكرنا قدر القبضة، فإذا زاد على ذلك جاز أن يأخذ وخصوصًا في الحج والعمرة.` },
    ],
  },
];
